const e=[{id:"sv-4-bb001",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:1,stem:"A fibre-provisioning team wants to understand what drives order-to-activation time. The team will test **OLT firmware** (3 levels), **QoS profile** (2 levels), **splitter ratio** (2 levels) in a full factorial and run **2 replicates** of every combination. How many experimental runs are needed?",options:["24","12","14","16"],answer:0,hint:"Treatment combinations = product of the numbers of levels; total runs = combinations × replicates.",steps:[{title:"Given",body:"3 factors with 3, 2, 2 levels; 2 replicates."},{title:"Formula",body:"$$N=\\left(\\prod_i L_i\\right)\\times r$$"},{title:"Substitute",body:"$$N=(3\\times 2\\times 2)\\times 2=12\\times 2$$"},{title:"Compute",body:"N = **24** runs, i.e. 12 treatment combinations each run 2 times."}],final:"N = 24 → answer **A**",whyWrong:["","This is the number of treatment combinations only; the replicates were not multiplied in.","The replicates were added to the combinations instead of multiplying them.","This assumes every factor has two levels. Here at least one factor has more than two."],trap:"Multiply levels (do not add them), then multiply by replicates.",bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb002",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:2,stem:"A contact-centre lead wants to understand drivers of average handle time. The team will test **routing rule** (4 levels), **IVR menu design** (3 levels), **staffing model** (2 levels) in a full factorial and run **3 replicates** of every combination. How many experimental runs are needed?",options:["24","27","72","144"],answer:2,hint:"Treatment combinations = product of the numbers of levels; total runs = combinations × replicates.",steps:[{title:"Given",body:"3 factors with 4, 3, 2 levels; 3 replicates."},{title:"Formula",body:"$$N=\\left(\\prod_i L_i\\right)\\times r$$"},{title:"Substitute",body:"$$N=(4\\times 3\\times 2)\\times 3=24\\times 3$$"},{title:"Compute",body:"N = **72** runs, i.e. 24 treatment combinations each run 3 times."}],final:"N = 72 → answer **C**",whyWrong:["This assumes every factor has two levels. Here at least one factor has more than two.","The replicates were added to the combinations instead of multiplying them.","","The total was doubled as if every run were measured twice; replicates are already counted once."],trap:"Multiply levels (do not add them), then multiply by replicates.",bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb003",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:2,stem:"A NOC team studies alarm-to-ticket time. The team will test **correlation engine** (2 levels), **alarm filter** (2 levels), **shift pattern** (3 levels), **ticket template** (2 levels) in a full factorial and run **2 replicates** of every combination. How many experimental runs are needed?",options:["24","48","18","32"],answer:1,hint:"Treatment combinations = product of the numbers of levels; total runs = combinations × replicates.",steps:[{title:"Given",body:"4 factors with 2, 2, 3, 2 levels; 2 replicates."},{title:"Formula",body:"$$N=\\left(\\prod_i L_i\\right)\\times r$$"},{title:"Substitute",body:"$$N=(2\\times 2\\times 3\\times 2)\\times 2=24\\times 2$$"},{title:"Compute",body:"N = **48** runs, i.e. 24 treatment combinations each run 2 times."}],final:"N = 48 → answer **B**",whyWrong:["This is the number of treatment combinations only; the replicates were not multiplied in.","","The levels were added instead of multiplied. A full factorial crosses every level of every factor.","This assumes every factor has two levels. Here at least one factor has more than two."],trap:"Multiply levels (do not add them), then multiply by replicates.",bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb004",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:2,stem:"A screening study on cloud-VM provisioning time has **5 two-level factors**. In the full $2^5$ factorial, how many effects (main effects plus all interactions) can be estimated?",options:["32","10","15","31"],answer:3,hint:"A $2^k$ full factorial has $2^k$ runs and can estimate $2^k-1$ effects (one degree of freedom goes to the mean).",steps:[{title:"Given",body:"k = 5 factors, each at 2 levels, one replicate."},{title:"Formula",body:"$$\\text{effects}=2^k-1=\\sum_{j=1}^{k}\\binom{k}{j}$$"},{title:"Compute",body:"$$2^5-1=2\\times 2\\times 2\\times 2\\times 2-1=32-1=31$$ That is 5 main effects + 10 two-factor + 10 three-factor + 5 four-factor + 1 five-factor interaction."}],final:"31 effects → answer **D**",whyWrong:["This counts every column of the design including the overall mean (the intercept), which is not an effect.","This is only the number of two-factor interactions.","This counts only main effects and two-factor interactions and forgets the higher-order interactions.",""],trap:"The intercept uses one degree of freedom but is not an effect.",bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb005",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:1,stem:"A Black Belt plans a two-level experiment with **6 factors** affecting billing-run duration. How many **two-factor interactions** exist?",options:["30","15","63","20"],answer:1,hint:"Two-factor interactions = number of ways to choose 2 factors from k.",steps:[{title:"Given",body:"k = 6 factors."},{title:"Formula",body:"$$\\binom{k}{2}=\\dfrac{k(k-1)}{2}$$"},{title:"Compute",body:"$$\\binom{6}{2}=\\dfrac{6\\times 5}{2}=15$$"}],final:"15 two-factor interactions → answer **B**",whyWrong:["Each pair was counted twice (AB and BA). Divide k(k−1) by 2.","","This is the total number of effects of all orders, not just two-factor interactions.","This is the number of three-factor interactions."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb006",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:2,stem:"An experiment on 5G small-cell throughput uses **6 two-level factors**. How many **three-factor interactions** can a full factorial estimate?",options:["120","15","20","57"],answer:2,hint:"Interactions of order j = number of ways to choose j factors from k.",steps:[{title:"Given",body:"k = 6, interaction order j = 3."},{title:"Formula",body:"$$\\binom{k}{3}=\\dfrac{k(k-1)(k-2)}{3\\times 2\\times 1}$$"},{title:"Compute",body:"$$\\binom{6}{3}=\\dfrac{6\\times 5\\times 4}{6}=\\dfrac{120}{6}=20$$"}],final:"20 three-factor interactions → answer **C**",whyWrong:["Ordered triples were counted. ABC, ACB, BAC … are the same interaction, so divide by 3! = 6.","This is the number of two-factor interactions.","","This is all interactions of every order, not only three-factor ones."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb007",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:1,stem:"In a two-level experiment on P2 incident MTTR, the average MTTR at the **high** level of *on-call engineers* is **3.4 h** and at the **low** level is **4.6 h**. What is the main effect of on-call engineers?",options:["−1.2 h","1.2 h","−0.6 h","4.0 h"],answer:0,hint:"Main effect = mean response at the high level − mean response at the low level.",steps:[{title:"Given",body:"$\\bar y_+=3.4$ h, $\\bar y_-=4.6$ h."},{title:"Formula",body:"$$E_A=\\bar y_{A+}-\\bar y_{A-}$$"},{title:"Compute",body:"$$E_A=3.4-4.6=-1.2\\text{ h}$$"},{title:"Interpret",body:"Moving from low to high staffing **reduces** MTTR by 1.2 h on average (the minus sign means a decrease). Do not confuse it with the coded coefficient: $$b_A=\\dfrac{E_A}{2}=-0.6$$"}],final:"Effect = −1.2 h → answer **A**",whyWrong:["","The subtraction was reversed. A main effect is (average at high) minus (average at low).","This is the coded regression coefficient (effect ÷ 2), not the effect.","This is the average of the two means (the grand mean), not the effect."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb008",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:2,stem:`A 2² experiment (2 replicates) studies **ticket-triage time (min)**. Factor A = AI auto-classification (off/on).

| Run | A | Time |
|---|---|---|
| 1 | − | 30 |
| 2 | + | 22 |
| 3 | − | 34 |
| 4 | + | 26 |
| 5 | − | 31 |
| 6 | + | 24 |
| 7 | − | 33 |
| 8 | + | 28 |

What is the main effect of A?`,options:["7 min","−3.5 min","−28 min","−7 min"],answer:3,hint:"Average the responses at A+ and at A−, then subtract: high − low.",steps:[{title:"Given",body:"A+ runs: 22, 26, 24, 28. A− runs: 30, 34, 31, 33."},{title:"Averages",body:"$$\\bar y_{A+}=\\dfrac{22+26+24+28}{4}=25\\qquad \\bar y_{A-}=\\dfrac{30+34+31+33}{4}=32$$"},{title:"Effect",body:"$$E_A=25-32=-7\\text{ min}$$"},{title:"Interpret",body:"Turning auto-classification on cuts triage time by about 7 minutes."}],final:"Effect of A = −7 min → answer **D**",whyWrong:["Low minus high was calculated. The effect is high minus low.","This is the coefficient in the coded model (effect ÷ 2).","The totals were subtracted without dividing by the four runs at each level.",""],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb009",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:2,stem:'A $2^4$ full factorial with **2 replicates** is run on IPTV channel-change delay. Every run is used to estimate every main effect ("hidden replication"). How many runs contribute to the **average at the high level** of factor A?',options:["2","16","8","32"],answer:1,hint:"In a balanced two-level design, half of all runs are at each level of every factor.",steps:[{title:"Given",body:"$N=2^4\\times 2=32$ runs."},{title:"Formula",body:"$$n_{A+}=\\dfrac{N}{2}$$"},{title:"Compute",body:"$$n_{A+}=\\dfrac{32}{2}=16$$"},{title:"Why it matters",body:"Each main effect compares 16 runs with 16 runs, so a factorial gives far more precise effect estimates than one-factor-at-a-time testing with the same budget."}],final:"n(A+) = 16 → answer **B**",whyWrong:["This is the number of replicates, not the number of runs at A+.","","This is the number of A+ runs in one replicate only; there are two replicates.","This is the total number of runs; only half of them are at A+."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb010",phase:4,topic:"4.3.1",qtype:"calculation",difficulty:3,stem:"In a 2² study on VoIP jitter (ms), the effect of **codec A** is **+4 ms** when **buffer B** is low, but **−2 ms** when B is high. What is the AB interaction effect?",options:["−6 ms","+3 ms","−3 ms","1 ms"],answer:2,hint:"Interaction AB = ½ × [(effect of A at B high) − (effect of A at B low)].",steps:[{title:"Given",body:"$E_{A|B-}=4$, $E_{A|B+}=-2$ ms."},{title:"Formula",body:"$$AB=\\dfrac{E_{A|B+}-E_{A|B-}}{2}$$"},{title:"Compute",body:"$$AB=\\dfrac{-2-4}{2}=\\dfrac{-6}{2}=-3\\text{ ms}$$"},{title:"Interpret",body:"The effect of the codec reverses with the buffer setting — a strong interaction. A and B must be interpreted together."}],final:"AB = −3 ms → answer **C**",whyWrong:["The difference was not halved. The interaction effect is half the change in the A effect across B.","The subtraction was reversed: take (A effect at B high) − (A effect at B low).","","Averaging the two A effects gives the main effect of A, not the interaction."],trap:"When the effect of one factor changes sign across another factor, never read the main effect on its own.",bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb011",phase:4,topic:"4.3.1",qtype:"concept",difficulty:1,stem:"What is the main purpose of a designed experiment (DOE)?",options:["To establish cause-and-effect between inputs (X’s) and an output (Y) by deliberately changing the X’s and observing Y","To monitor a running process over time and detect special-cause variation","To describe relationships found in historical data without changing the process","To check that the measurement system is accurate and precise"],answer:0,hint:"DOE = active, planned changes to X’s → measure Y → model Y = f(X).",steps:[{title:"Key idea",body:"A designed experiment **actively** sets the X’s at chosen levels, in a planned pattern, and measures the response. Because the experimenter controls the X’s (and randomizes), changes in Y can be attributed to them: Y = f(X)."},{title:"Eliminate look-alikes",body:"SPC watches a process, regression on history shows association, MSA checks the gauge. None of them deliberately manipulates the X’s."}],final:"Cause-and-effect via deliberate change → answer **A**",whyWrong:["","That is the job of statistical process control (SPC), used in Control.","That is a passive (observational) study. It can show association but not prove cause.","That is measurement system analysis (MSA), done before an experiment."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb012",phase:4,topic:"4.3.1",qtype:"scenario",difficulty:2,stem:"A fibre-install team has a list of **11 candidate X’s** that might affect installation time, a limited budget and no idea which X’s matter. What should the **objective** of the first experiment be?",options:["Optimization — fit a response-surface model to find the best settings of all 11 X’s","Characterization — run a full factorial in all 11 X’s to estimate every interaction","Robustness — make installation time insensitive to the weather","Screening — find the vital few X’s with a small fractional or Plackett–Burman design"],answer:3,hint:"Many X’s + little knowledge → screen first; few X’s → characterize; vital X’s known → optimize.",steps:[{title:"Key idea",body:"Experimentation is **sequential**. With many candidate X’s, the first objective is **screening**: separate the vital few from the trivial many with as few runs as possible."},{title:"Apply",body:"Eleven X’s and a tight budget point to a Resolution III fractional factorial or a 12-run Plackett–Burman design."},{title:"Next",body:"The vital few found here are then characterized (full factorial) and optimized (response surface)."}],final:"Screening objective → answer **D**",whyWrong:["Optimization comes later, once only a few vital X’s remain. Fitting curvature for 11 X’s would need a very large design.","A $2^{11}$ full factorial needs 2,048 runs. That is wasteful before the vital few are known.","Robust design needs known control and noise factors; the team does not yet know which X’s matter.",""],trap:"Do not jump to optimization or full factorials before screening when there are many X’s.",bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb013",phase:4,topic:"4.3.1",qtype:"scenario",difficulty:2,stem:"Screening showed that **three X’s** (router model, MTU size, QoS policy) drive packet loss. The team now wants the **size of each effect and every interaction**. Which objective and design fit best?",options:["Screening with a Resolution III fractional factorial","Robustness with an inner and outer array","A one-factor-at-a-time study changing each X in turn","Characterization with a full $2^3$ factorial (replicated)"],answer:3,hint:"Characterization objective = quantify main effects and interactions of the few vital X’s → full factorial.",steps:[{title:"Key idea",body:"**Characterization** describes how each vital X and each interaction affects Y. A full factorial estimates all of them with no aliasing."},{title:"Apply",body:"With 3 factors, a $2^3$ full factorial needs only 8 runs per replicate, so it is affordable and replication gives an error estimate."}],final:"Characterize with a full factorial → answer **D**",whyWrong:["Screening is already done. Resolution III would alias main effects with two-factor interactions, hiding the interactions the team needs.","Robust design targets insensitivity to noise factors, not estimation of all effects.","OFAT cannot estimate interactions at all.",""],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb014",phase:4,topic:"4.3.1",qtype:"scenario",difficulty:2,stem:"A data-centre team knows that **supply-air temperature** and **fan speed** are the vital X’s for server inlet temperature. Earlier runs showed the response **bends** (it is not a straight line). They now want the settings that give the **best** inlet temperature. What is the objective?",options:["Optimization — use a response surface design that can fit curvature","Screening — use a Plackett–Burman design","Characterization — use a two-level full factorial only","Verification — run a single confirmation run at today’s settings"],answer:0,hint:"Optimization objective = find best settings; needs a model with quadratic terms (≥ 3 levels per factor).",steps:[{title:"Key idea",body:"**Optimization** searches for factor settings that hit a target or a maximum/minimum. When the response curves, the model needs squared terms, which a two-level design cannot estimate."},{title:"Apply",body:"A central composite or Box–Behnken design adds the extra levels needed to fit curvature and find the optimum."}],final:"Optimization with RSM → answer **A**",whyWrong:["","Screening finds vital X’s; they are already known.","A two-level design fits only straight lines (plus interaction twist). It cannot locate an optimum on a curved surface.","A confirmation run checks a prediction after optimization; it does not find the optimum."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb015",phase:4,topic:"4.3.1",qtype:"scenario",difficulty:2,stem:"A mobile operator wants call-setup success to stay high **whatever the traffic load**, which it cannot control. It can control antenna tilt and handover margin. What type of experimental objective is this?",options:["Screening — find which of many factors matter","Optimization — maximize Y at a single fixed traffic load","Robustness — choose control-factor settings that make Y insensitive to the noise factor","Characterization — estimate the effect of traffic load on Y"],answer:2,hint:"Robust design: control factors are set so that variation from noise factors has least effect on Y.",steps:[{title:"Key idea",body:"A **noise factor** affects Y but cannot (or will not) be controlled in normal operation. A **robustness** objective looks for control-factor settings where Y changes little as the noise factor varies."},{title:"Apply",body:"Traffic load is the noise factor; antenna tilt and handover margin are control factors. Look for a control × noise interaction that flattens the response."}],final:"Robustness objective → answer **C**",whyWrong:["The controllable factors are already known; the aim is insensitivity to an uncontrollable factor.","Optimizing at one traffic load ignores how performance changes as load varies.","","Traffic load cannot be changed in operation, so knowing its effect alone does not help; the goal is to reduce its impact."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb016",phase:4,topic:"4.3.1",qtype:"concept",difficulty:1,stem:"In DOE language, what is the **response**?",options:["An input variable that the experimenter sets at chosen levels","The measured output (Y) whose behaviour the experiment is trying to explain or improve","A specific setting of a factor, such as “high” or “low”","One complete repeat of the whole set of treatment combinations"],answer:1,hint:"Factor = X; level = setting of X; response = Y.",steps:[{title:"Key idea",body:"The **response** is the output Y, e.g. MTTR, throughput or handle time. It should be measurable, ideally continuous, with a capable measurement system."},{title:"Eliminate look-alikes",body:"Factor, level and replicate describe the inputs and the structure of the design, not the output."}],final:"Response = Y → answer **B**",whyWrong:["That is a factor (an X).","","That is a level.","That is a replicate."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb017",phase:4,topic:"4.3.1",qtype:"missing-word",difficulty:1,stem:"Complete the sentence: “Each unique combination of factor levels tested in an experiment, such as A high / B low / C high, is called a [?].”",options:["replicate","block","treatment combination","response"],answer:2,hint:"A treatment (treatment combination) = one specific set of levels, one per factor.",steps:[{title:"Key idea",body:"A $2^3$ design has 8 **treatment combinations**. Each time one is executed it is a **run**; repeating the whole set is a **replicate**."},{title:"Apply",body:"A high / B low / C high is one of the 8 combinations."}],final:"Treatment combination → answer **C**",whyWrong:["A replicate is a full repeat of all treatment combinations, not one combination.","A block is a group of runs made under similar nuisance conditions (e.g. same day).","","The response is the output Y measured for each run."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb018",phase:4,topic:"4.3.1",qtype:"concept",difficulty:2,stem:"Which description matches a **replicate** (as opposed to a **repeat**) in a designed experiment?",options:["The same run is measured several times without resetting the factors","The treatment combination is set up again from scratch and run independently, so the result includes set-up-to-set-up variation","A different factor is added to the experiment at a later stage","The run order is changed to a random sequence"],answer:1,hint:"Replicate = independent re-run of the treatment (new set-up). Repeat = several readings from one set-up.",steps:[{title:"Key idea",body:"A **replicate** resets and re-runs the treatment, so the spread between replicates estimates the true experimental (pure) error. A **repeat** only re-measures the same run."},{title:"Why it matters",body:"Treating repeats as replicates understates error, so effects look more significant than they are."}],final:"Replicate = independent re-run → answer **B**",whyWrong:["That is a repeat (repeated measurement). It shows measurement noise only, not run-to-run variation.","","Adding a factor is augmenting the design, not replicating it.","That is randomization."],trap:"Repeats understate the error term; only true replicates give a valid estimate of pure error.",bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb019",phase:4,topic:"4.3.1",qtype:"concept",difficulty:1,stem:"What does it mean when two factors **interact**?",options:["The two factors are strongly correlated with each other in the design","Both factors have large main effects","The two factors cannot both be changed in the same experiment","The effect of one factor on Y depends on the level of the other factor"],answer:3,hint:"Interaction: the effect of A is different at different levels of B (non-parallel lines on an interaction plot).",steps:[{title:"Key idea",body:"An **interaction** means the factors do not act independently: the change in Y when A moves from low to high is different when B is low than when B is high."},{title:"How it shows",body:"On an interaction plot the lines are not parallel (they may even cross)."}],final:"Effect of one depends on the other → answer **D**",whyWrong:["That is collinearity. In an orthogonal design factors are uncorrelated, yet they can still interact.","Large main effects can exist without any interaction.","Factorial designs change both together precisely so interactions can be seen.",""],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb020",phase:4,topic:"4.3.1",qtype:"statements",difficulty:2,stem:`Which statements about designed experiments versus passive (historical) data analysis are correct?

1. In a DOE the experimenter deliberately sets the X’s.
2. Passive data can prove cause-and-effect if the sample is large enough.
3. Randomizing the run order protects against lurking variables.
4. A factorial DOE can estimate interactions between X’s.`,options:["1, 3 and 4 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],answer:0,hint:"DOE = active control + randomization → causal claims; passive data → association.",steps:[{title:"Check each",body:"1 True — active manipulation is what makes it an experiment. 2 False — lurking variables can drive both X and Y in historical data. 3 True — randomization spreads unknown nuisance effects across all runs. 4 True — crossing factors lets interactions be estimated."},{title:"Decide",body:"Statements 1, 3 and 4 are correct."}],final:"1, 3, 4 → answer **A**",whyWrong:["","Statement 2 is false: a large passive data set still shows association only. Statements 3 and 4 are true.","Statement 2 is false, and statement 1 (deliberate setting of X’s) is the defining feature of a DOE.","Statement 2 is false. Sample size does not turn correlation into causation."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb021",phase:4,topic:"4.3.1",qtype:"not-except",difficulty:1,stem:"Which of the following is NOT a typical objective of a designed experiment?",options:["Screening many X’s to find the vital few","Finding the factor settings that optimize Y","Making Y insensitive to noise factors","Detecting special-cause variation in a stable, running process"],answer:3,hint:"DOE objectives: screen, characterize, optimize, make robust (and confirm). Monitoring belongs to SPC.",steps:[{title:"Key idea",body:"Typical DOE objectives are **screening**, **characterization**, **optimization** and **robustness**."},{title:"Find the odd one out",body:"Watching a running process for special causes is the job of a control chart in the Control phase."}],final:"SPC monitoring is not a DOE objective → answer **D**",whyWrong:["Screening is a standard DOE objective.","Optimization is a standard DOE objective (often with response surface methods).","Robustness is a standard DOE objective.",""],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb022",phase:4,topic:"4.3.1",qtype:"true-false",difficulty:1,stem:"True or false: in a designed experiment, the levels of the factors are chosen and set by the experimenter, rather than simply recorded as they happen.",options:["True","False"],answer:0,hint:"Experiment = active manipulation of X’s.",steps:[{title:"Key idea",body:"In a DOE the experimenter **chooses** the factors, the levels and the run order. In an observational study the X’s vary on their own."},{title:"Consequence",body:"Active control plus randomization is what allows cause-and-effect conclusions."}],final:"Levels are set by the experimenter → answer **True**",whyWrong:["","This is the defining feature of an experiment: the X’s are deliberately set, not just observed."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb023",phase:4,topic:"4.3.1",qtype:"true-false",difficulty:2,stem:"True or false: if an effect in a designed experiment is statistically significant (p < 0.05), it is always large enough to matter to the customer or the business.",options:["True","False"],answer:1,hint:"Statistical significance ≠ practical significance.",steps:[{title:"Key idea",body:"With enough runs, even a tiny effect becomes statistically significant. Whether it matters is a **practical** question: compare its size with the improvement the objective requires."},{title:"Apply",body:"A significant 2-second cut in a 4-hour MTTR is real but probably not worth a process change."}],final:"Not always practically significant → answer **False**",whyWrong:["Statistical significance only says the effect is unlikely to be zero. Its size must still be judged against the practical need.",""],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb024",phase:4,topic:"4.3.1",qtype:"sequence",difficulty:2,stem:`Put these DOE planning steps in the correct order:

P. Choose the experimental design
Q. State the objective and define the response
R. Run the experiment in random order
S. Select the factors and their levels
T. Analyze the data and run confirmation tests`,options:["S → Q → P → R → T","Q → P → S → R → T","Q → S → P → R → T","Q → S → R → P → T"],answer:2,hint:"Objective/response → factors & levels → design → randomized runs → analysis & confirmation.",steps:[{title:"Key idea",body:"Planning starts with **why** (objective and a measurable response), then **what** (factors and levels), then **how** (design and run order)."},{title:"Finish",body:"Only after the randomized runs are complete is the data analyzed, and the predicted best settings are confirmed."}],final:"Q → S → P → R → T → answer **C**",whyWrong:["Factors cannot be chosen sensibly before the objective and the response are agreed.","The design depends on how many factors and levels there are, so factors come before the design.","","The design must be chosen before any runs are made."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb025",phase:4,topic:"4.3.1",qtype:"best-action",difficulty:2,stem:"A team is about to start a DOE on **first-time-right order activation**. In the kick-off meeting it becomes clear that two departments define “first-time-right” differently and nobody has checked how it is recorded. What is the BEST action?",options:["Start the runs now and agree the definition during analysis","Agree an operational definition of the response and verify the measurement system before running the experiment","Add more replicates to average out the disagreement","Switch to a fractional factorial to save runs"],answer:1,hint:"A DOE is only as good as its response: clear operational definition + capable measurement system first.",steps:[{title:"Key idea",body:"The objective and the response are defined first. The response needs an **operational definition** and an acceptable **MSA** (e.g. attribute agreement or Gage R&R)."},{title:"Apply",body:"Fix the definition and check the recording process before any run is made."}],final:"Define Y and check MSA first → answer **B**",whyWrong:["If the response is not measured consistently, the experiment cannot detect real effects; the data would be wasted.","","Replication reduces random error. It does not fix a biased or inconsistent definition of Y.","The number of runs is not the problem; the response is undefined."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb026",phase:4,topic:"4.3.1",qtype:"concept",difficulty:1,stem:"What is a **noise factor** in experimental design?",options:["A variable that affects Y but cannot, or will not, be controlled in normal operation","A factor whose effect is not statistically significant","Random measurement error from the gauge","Any factor set at its low level"],answer:0,hint:"Control factors can be set in operation; noise factors cannot (but may be varied deliberately in a robustness test).",steps:[{title:"Key idea",body:"Examples of noise factors: customer traffic load, weather, ambient temperature. They are real causes of variation in Y but are not under the process owner’s control."},{title:"Use",body:"Robust design varies them on purpose during the experiment to find control settings that resist them."}],final:"Uncontrollable X → answer **A**",whyWrong:["","An insignificant factor is just an unimportant X; it is not called a noise factor.","Measurement error is part of the experimental error, not a factor.","Levels describe settings, not the type of factor."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb027",phase:4,topic:"4.3.1",qtype:"concept",difficulty:2,stem:"Why is a **continuous** response (e.g. handle time in seconds) usually preferred to a **pass/fail** response in a DOE?",options:["Pass/fail responses cannot be analyzed statistically","Continuous responses never need a measurement system analysis","Continuous responses remove the need to randomize","It carries more information per run, so effects can be detected with far fewer runs"],answer:3,hint:"Information per observation: continuous ≫ attribute.",steps:[{title:"Key idea",body:"A pass/fail result tells only which side of a line each run fell. A continuous measure shows **how far**, so the same effect is visible with far fewer runs."},{title:"Apply",body:"Measure handle time directly rather than “within target: yes/no”, then compare with the target afterwards."}],final:"More information per run → answer **D**",whyWrong:["Attribute responses can be analyzed (e.g. logistic regression), but they need many more runs.","Every response needs an adequate measurement system.","Randomization is needed whatever the type of response.",""],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb028",phase:4,topic:"4.3.1",qtype:"concept",difficulty:1,stem:"After a DOE, the model predicts that a new combination of settings will give the best result. What is the purpose of the **confirmation run**?",options:["To replace the analysis if the p-values are borderline","To run the process at the chosen settings and check that the actual results agree with the model’s prediction","To estimate the pure error for the ANOVA table","To randomize the run order of the original experiment"],answer:1,hint:"Confirm: predicted Y at best settings vs observed Y (inside the prediction interval?).",steps:[{title:"Key idea",body:"The best settings are often a combination never actually run. A **confirmation run** checks that reality matches the prediction before the change is rolled out."},{title:"Decide",body:"If results fall inside the prediction interval the model is supported; if not, something was missed (e.g. an interaction or curvature)."}],final:"Verify the prediction → answer **B**",whyWrong:["Confirmation follows the analysis; it does not replace it.","","Pure error comes from replicates and center points within the experiment.","Randomization happens before and during the experiment."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb029",phase:4,topic:"4.3.1",qtype:"scenario",difficulty:2,stem:"An interaction plot for **average speed of answer** shows two lines for *staffing model* (pooled vs skills-based) across *routing rule* (A vs B). The lines **cross**: pooled is better under rule A, skills-based is better under rule B. What should the team conclude?",options:["Staffing model has no effect because its main effect is close to zero","Routing rule should be dropped from the study","The best staffing model depends on the routing rule, so the two factors must be chosen together","The plot shows a measurement problem because lines should be parallel"],answer:2,hint:"Crossing / non-parallel lines on an interaction plot → interaction → interpret factors together.",steps:[{title:"Key idea",body:"Parallel lines = no interaction. Crossing lines = strong interaction: the effect of one factor reverses with the other."},{title:"Apply",body:"Choose the **combination** (pooled + A, or skills-based + B) with the best response rather than each factor separately."}],final:"Choose the factors together → answer **C**",whyWrong:["A main effect near zero can hide a large effect that changes direction; the crossing lines show staffing matters a lot.","Routing rule is part of a strong interaction and cannot be dropped.","","Non-parallel lines are the signature of an interaction, not a measurement fault."],trap:"A small main effect does not mean a factor is unimportant when it is part of a strong interaction.",bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb030",phase:4,topic:"4.3.1",qtype:"concept",difficulty:1,stem:"In which DMAIC phase are designed experiments **most** used to find and confirm the best settings of the vital X’s?",options:["Improve","Define","Measure","Control"],answer:0,hint:"Analyze identifies likely X’s; Improve uses DOE to quantify them and set the best levels.",steps:[{title:"Key idea",body:"Designed experiments are the core tool of **Improve**: they establish Y = f(X) for the vital few and find the settings that give the target performance."},{title:"Note",body:"Simple screening experiments may also appear late in Analyze to confirm root causes."}],final:"Improve → answer **A**",whyWrong:["","Define sets the problem, scope and CTQs; no X’s have been studied yet.","Measure establishes the baseline and the measurement system.","Control sustains the gains with control plans and SPC."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb031",phase:4,topic:"4.3.1",qtype:"best-action",difficulty:2,stem:"A DOE on network-change implementation shows a **significant** effect (p = 0.001): a new peer-review step cuts change duration by **4 minutes** on a **6-hour** average. The review step costs one extra engineer per shift. What is the BEST next action?",options:["Implement immediately because p = 0.001 proves the effect is important","Repeat the experiment until the p-value is smaller","Discard the result because the effect is not significant","Judge the practical value of a 4-minute gain against the cost before deciding to implement"],answer:3,hint:"Statistical significance → is it real? Practical significance → does it matter enough to act?",steps:[{title:"Key idea",body:"Every effect should be judged on two questions: is it real (p-value) and is it big enough to matter (effect size vs objective and cost)."},{title:"Apply",body:"Four minutes on six hours is about 1%. Compare with the cost of an extra engineer before implementing."}],final:"Check practical significance → answer **D**",whyWrong:["A small p-value shows the effect is real, not that it is worth the cost.","The effect is already clearly significant; more runs do not make it bigger.","p = 0.001 is significant; the issue is practical importance.",""],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb032",phase:4,topic:"4.3.1",qtype:"missing-word",difficulty:1,stem:"Complete the sentence: “The specific value or setting at which a factor is tested, for example 1,500 bytes vs 9,000 bytes for MTU size, is called a [?].”",options:["level","response","run","block"],answer:0,hint:"Factor = the X; level = the value the X is set to.",steps:[{title:"Key idea",body:"A two-level design tests each factor at a low (−1) and a high (+1) **level**."},{title:"Apply",body:"1,500 and 9,000 bytes are the two levels of the factor “MTU size”."}],final:"Level → answer **A**",whyWrong:["","The response is the measured output Y.","A run is one execution of a treatment combination.","A block is a group of similar runs used to remove a nuisance source."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb033",phase:4,topic:"4.3.1",qtype:"sequence",difficulty:2,stem:"A Black Belt plans a series of experiments on network latency. In which order are the experimental **objectives** usually pursued?",options:["Optimization → screening → characterization","Screening → characterization → optimization","Characterization → screening → optimization","Screening → optimization → characterization"],answer:1,hint:"Sequential experimentation: many X’s → few X’s → best settings.",steps:[{title:"Key idea",body:"Experiments are run in a **sequence**, each one building on the last: screen many X’s cheaply, characterize the vital few fully, then optimize."},{title:"Why",body:"This keeps the total number of runs low and spends the budget where the knowledge is needed."}],final:"Screen → characterize → optimize → answer **B**",whyWrong:["Optimizing before knowing which X’s matter wastes runs on trivial factors.","","Characterizing all candidate X’s before screening would need a very large full factorial.","Optimization needs a good understanding of effects and interactions first."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb034",phase:4,topic:"4.3.1",qtype:"best-action",difficulty:1,stem:"A manager asks the Black Belt to “test everything we can think of on the billing system and see what happens.” What is the BEST first step?",options:["Choose the largest design the budget allows and start testing","Run one-factor-at-a-time tests on every setting","Write a clear objective that states the response, the improvement needed and the scope of factors","Collect a year of historical data and run a regression instead"],answer:2,hint:"Every experiment starts with a written objective: what Y, what change, which X’s, what constraints.",steps:[{title:"Key idea",body:"The objective drives every other choice: response, factors, levels, design type and the number of runs."},{title:"Apply",body:"For example: “Reduce billing-run time (Y, minutes) by 20% by understanding the effect of batch size, thread count and DB index settings.”"}],final:"Write the objective first → answer **C**",whyWrong:["Without an objective there is no basis for choosing factors, levels or the design.","OFAT is inefficient and still needs an objective; it also misses interactions.","","Passive data can help, but the first step is still a clear objective."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb035",phase:4,topic:"4.3.1",qtype:"concept",difficulty:2,stem:"Why is a factorial experiment more efficient than changing **one factor at a time** (OFAT)?",options:["It needs no replication because factorial designs have no experimental error","It always uses fewer total runs than OFAT","Every run is used to estimate every main effect, and interactions can be estimated as well","It does not need randomization because all factors change together"],answer:2,hint:"Factorial: all runs inform all effects (hidden replication) + interactions; OFAT: neither.",steps:[{title:"Key idea",body:"In a factorial, each main effect compares half of all runs with the other half, so precision is high for the budget (**hidden replication**). Crossing the factors also reveals interactions."},{title:"OFAT weakness",body:"OFAT holds other factors fixed, so it cannot see interactions and can miss the real optimum."}],final:"All runs used + interactions → answer **C**",whyWrong:["All experiments have error; replication is still needed to estimate it.","For a very small number of runs OFAT can use fewer, but it gives less information per run and no interactions.","","Randomization is still essential."],bookRef:"Syllabus 4.3.1"},{id:"sv-4-bb036",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:1,stem:"A team tests **5 two-level factors** for VPN tunnel set-up time using **one-factor-at-a-time (OFAT)**: one baseline run, then each factor is switched to its other level in turn (others at baseline), with no replication. How many runs does this OFAT plan need, and how many would a $2^5$ full factorial need?",options:["6 runs (OFAT) vs 32 runs (full factorial)","5 runs (OFAT) vs 32 runs (full factorial)","10 runs (OFAT) vs 32 runs (full factorial)","6 runs (OFAT) vs 10 runs (full factorial)"],answer:0,hint:"OFAT = 1 baseline + (L − 1) runs per factor; full factorial = L^k runs.",steps:[{title:"Given",body:"k = 5 factors, L = 2 levels, one replicate."},{title:"Formulas",body:"$$N_{OFAT}=1+k(L-1)\\qquad N_{full}=L^k$$"},{title:"Compute",body:"$$N_{OFAT}=1+5\\times 1=6\\qquad N_{full}=2^5=32$$"},{title:"Interpret",body:"OFAT is cheaper here, but each effect rests on a single comparison of two runs and no interaction can be estimated. The factorial uses all 32 runs for every effect."}],final:"OFAT 6, full 32 → answer **A**",whyWrong:["","The baseline run was forgotten; OFAT needs one run with all factors at baseline plus one run per changed factor.","Each factor was counted at both levels; the baseline already covers every factor’s first level.","A full factorial crosses every level of every factor: $2^k$ runs, not 2k."],trap:"Fewer runs is not the same as more information: OFAT gives no interactions and poor precision.",bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb037",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:2,stem:"An OFAT study varies **4 factors**, each at **3 levels**, for DSL line-sync rate. It starts with one baseline run and then moves each factor through its other levels while the rest stay at baseline. How many runs are needed (no replication)?",options:["12","9","8","81"],answer:1,hint:"OFAT runs = 1 + k(L − 1).",steps:[{title:"Given",body:"k = 4, L = 3."},{title:"Formula",body:"$$N_{OFAT}=1+k(L-1)$$"},{title:"Compute",body:"$$N_{OFAT}=1+4\\times(3-1)=1+8=9$$"},{title:"Compare",body:"A full $3^4$ factorial would need 81 runs but would show every interaction."}],final:"9 runs → answer **B**",whyWrong:["Every level of every factor was counted, but the baseline run already includes one level of each factor.","","The baseline run itself was not counted.","This is the number of runs for a full 3-level factorial, not OFAT."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb038",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:1,stem:"A three-level full factorial is planned for Wi-Fi roaming time with **3 factors** (each at **3 levels**) and **2 replicates**. How many runs are needed?",options:["27","18","16","54"],answer:3,hint:"Full factorial runs = L^k × replicates.",steps:[{title:"Given",body:"L = 3, k = 3, r = 2."},{title:"Formula",body:"$$N=L^k\\times r$$"},{title:"Compute",body:"$$N=3^3\\times 2=27\\times 2=54$$"},{title:"Note",body:"Three-level designs grow fast ($3^5$ = 243 per replicate), which is why two-level designs plus center points are usually preferred."}],final:"N = 54 → answer **D**",whyWrong:["Only one replicate was counted.","Levels were multiplied by the number of factors instead of being raised to the power k.","This is a two-level design; here each factor has three levels.",""],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb039",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:2,stem:"A $2^3$ design on fibre-splice loss is replicated **4 times**, one replicate per day, and **day** is used as a block. How many degrees of freedom does the **block** term use in the ANOVA?",options:["4","7","3","31"],answer:2,hint:"Degrees of freedom for a blocking factor = number of blocks − 1.",steps:[{title:"Given",body:"b = 4 blocks (days); $N=2^3\\times 4=32$ runs."},{title:"Formula",body:"$$df_{block}=b-1$$"},{title:"Compute",body:"$$df_{block}=4-1=3$$"},{title:"Why it matters",body:"Removing day-to-day variation costs 3 df from the error term but can make the error much smaller."}],final:"df(block) = 3 → answer **C**",whyWrong:["The number of blocks was used. A term with b levels uses b − 1 degrees of freedom.","This is the number of degrees of freedom for all the treatment effects in one replicate (8 − 1).","","This is the total degrees of freedom for all runs."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb040",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:1,stem:"A $2^4$ design with **2 replicates** on call-centre abandonment rate is split evenly into **4 blocks** (one per shift). How many runs are in each block?",options:["4","8","16","32"],answer:1,hint:"Runs per block = total runs ÷ number of blocks.",steps:[{title:"Given",body:"$N=2^4\\times 2=32$ runs; b = 4."},{title:"Formula",body:"$$n_{block}=\\dfrac{N}{b}$$"},{title:"Compute",body:"$$n_{block}=\\dfrac{32}{4}=8$$"}],final:"8 runs per block → answer **B**",whyWrong:["Only one replicate (16 runs) was divided among the blocks.","","The runs were split by replicate (2) instead of by the 4 blocks.","This is the total number of runs; it still has to be shared out across the blocks."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb041",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:2,stem:"A Black Belt wants to screen **9 two-level factors** for mobile-app crash rate with a **Plackett–Burman** design. What is the **smallest** number of runs that can estimate all 9 main effects?",options:["9","16","10","12"],answer:3,hint:"Plackett–Burman designs have N runs, where N is a multiple of 4, and can screen up to N − 1 factors.",steps:[{title:"Given",body:"k = 9 factors."},{title:"Rule",body:"$$N\\ \\text{is a multiple of 4 and}\\ N-1\\ge k$$"},{title:"Compute",body:"$$N\\ge k+1=10\\Rightarrow N=4\\times\\left\\lceil\\dfrac{10}{4}\\right\\rceil=12$$"},{title:"Interpret",body:"12 runs give 11 columns: 9 for the factors and 2 spare (dummy) columns that help estimate error."}],final:"N = 12 → answer **D**",whyWrong:["The number of runs must be at least k + 1, and Plackett–Burman run sizes are multiples of 4.","This is the smallest two-level fractional factorial (power of 2), not the smallest Plackett–Burman design.","k + 1 is the minimum count, but Plackett–Burman sizes must be multiples of 4.",""],trap:"Plackett–Burman designs are Resolution III: main effects are partially aliased with two-factor interactions.",bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb042",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:3,stem:"A Black Belt wants to screen **19 two-level factors** for mobile-app crash rate with a **Plackett–Burman** design. What is the **smallest** number of runs that can estimate all 19 main effects?",options:["20","19","24","32"],answer:0,hint:"Plackett–Burman designs have N runs, where N is a multiple of 4, and can screen up to N − 1 factors.",steps:[{title:"Given",body:"k = 19 factors."},{title:"Rule",body:"$$N\\ \\text{is a multiple of 4 and}\\ N-1\\ge k$$"},{title:"Compute",body:"$$N\\ge k+1=20\\Rightarrow N=4\\times\\left\\lceil\\dfrac{20}{4}\\right\\rceil=20$$"},{title:"Interpret",body:"20 runs give 19 columns: 19 for the factors and 0 spare (dummy) columns that help estimate error."}],final:"N = 20 → answer **A**",whyWrong:["","The number of runs must be at least k + 1, and Plackett–Burman run sizes are multiples of 4.","This works but is not the smallest Plackett–Burman size that fits.","This is the smallest two-level fractional factorial (power of 2), not the smallest Plackett–Burman design."],trap:"Plackett–Burman designs are Resolution III: main effects are partially aliased with two-factor interactions.",bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb043",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:1,stem:"The test lab can afford **50 runs** for a $2^4$ full factorial on router boot time. How many **complete replicates** can be run?",options:["3","3.125","4","12"],answer:0,hint:"Complete replicates = floor(budget ÷ runs per replicate).",steps:[{title:"Given",body:"Budget = 50 runs; one replicate of $2^4$ = 16 runs."},{title:"Formula",body:"$$r=\\left\\lfloor\\dfrac{\\text{budget}}{2^k}\\right\\rfloor$$"},{title:"Compute",body:"$$\\dfrac{50}{16}=3.125\\Rightarrow r=3$$"},{title:"Use the rest",body:"The 2 spare runs could be center points or confirmation runs."}],final:"3 replicates → answer **A**",whyWrong:["","A replicate must be complete; a fraction of a replicate leaves the design unbalanced.","The result was rounded up, which would need more runs than the budget allows.","The budget was divided by the number of factors (4) instead of the runs per replicate (16)."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb044",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:2,stem:"A **Box–Behnken** design for **3 factors** (edge midpoints plus center points) is planned with **3 center points** to optimize data-centre PUE. How many runs is that?",options:["17","27","12","15"],answer:3,hint:"Box–Behnken (k = 3): 2k(k − 1) edge-midpoint runs + center points.",steps:[{title:"Given",body:"k = 3, center points = 3."},{title:"Formula",body:"$$N_{BBD}=2k(k-1)+n_c$$"},{title:"Compute",body:"$$N=2\\times 3\\times 2+3=12+3=15$$"},{title:"Note",body:"Box–Behnken never runs all factors at their extremes at once, which is useful when corner combinations are unsafe."}],final:"N = 15 → answer **D**",whyWrong:["This is a central composite design (cube + axial + center), not a Box–Behnken design.","This is a full three-level factorial.","The center points were left out.",""],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb045",phase:4,topic:"4.3.2",qtype:"calculation",difficulty:2,stem:"A screening study on 7 factors uses a $2^{7-3}$ fractional factorial instead of the full $2^7$. By what percentage does this cut the number of runs?",options:["12.5%","42.9%","87.5%","75%"],answer:2,hint:"Fraction kept = $\\dfrac{1}{2^p}$; saving = 1 − fraction kept.",steps:[{title:"Given",body:"Full: $2^7$ = 128 runs. Fraction: $2^4$ = 16 runs."},{title:"Formula",body:"$$\\text{saving}=1-\\dfrac{2^{k-p}}{2^k}=1-\\dfrac{1}{2^p}$$"},{title:"Compute",body:"$$1-\\dfrac{16}{128}=1-0.125=0.875$$"},{title:"Interpret",body:"An 87.5% saving, paid for with aliasing between effects."}],final:"87.5% fewer runs → answer **C**",whyWrong:["This is the fraction of runs that is kept (one-eighth), not the saving.","The saving was taken as p ÷ k = 3 ÷ 7; runs fall by powers of 2, not linearly.","","This is the saving for a quarter fraction ($2^{k-2}$), not an eighth fraction."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb046",phase:4,topic:"4.3.2",qtype:"concept",difficulty:1,stem:"R. A. Fisher’s three basic principles of experimental design are:",options:["Randomization, standardization and inspection","Randomization, replication and blocking","Replication, measurement and control charting","Screening, optimization and confirmation"],answer:1,hint:"Randomize (protect), replicate (estimate error), block (remove known nuisance).",steps:[{title:"Key idea",body:"**Randomization** protects against unknown nuisance variables; **replication** estimates pure error and improves precision; **blocking** removes the effect of known nuisance variables."},{title:"Apply",body:"Together they make the comparison between treatments fair and the error estimate valid."}],final:"Randomization, replication, blocking → answer **B**",whyWrong:["Standardization and inspection are control activities, not design principles.","","Control charting is SPC; measurement is a prerequisite, not a design principle.","These are experimental objectives or stages, not design principles."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb047",phase:4,topic:"4.3.2",qtype:"concept",difficulty:1,stem:"What is the main purpose of **randomizing the run order** in an experiment?",options:["To spread the effect of unknown or uncontrolled variables (e.g. time drift) evenly across the treatments so they do not bias the effects","To reduce the total number of runs needed","To make the analysis easier to calculate by hand","To ensure that each factor is tested at both levels"],answer:0,hint:"Randomization = insurance against lurking variables that change during the experiment.",steps:[{title:"Key idea",body:"If runs are made in standard order, anything that drifts over time (load, temperature, staff fatigue) becomes confounded with the factors that change slowly in that order."},{title:"Apply",body:"A random order turns those drifts into random error rather than a false effect."}],final:"Protect against lurking variables → answer **A**",whyWrong:["","Randomization changes the order, not the number, of runs.","Random order makes no difference to the arithmetic.","Balance is guaranteed by the design matrix, not by randomization."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb048",phase:4,topic:"4.3.2",qtype:"concept",difficulty:1,stem:"An experiment on ticket-resolution time must run across **two shifts** with different teams. What does **blocking** by shift achieve?",options:["It lets the team estimate the interaction between shift and every factor","It removes the known shift-to-shift difference from the error, so factor effects are estimated more precisely","It makes randomization unnecessary","It doubles the number of effects that can be estimated"],answer:1,hint:"“Block what you can, randomize what you cannot.”",steps:[{title:"Key idea",body:"A **block** is a group of runs made under similar conditions. Each block contains a balanced set of treatments, so the block difference is separated out and does not inflate the error or bias the effects."},{title:"Apply",body:"Put a balanced half (or full replicate) in each shift and randomize run order inside each shift."}],final:"Remove known nuisance variation → answer **B**",whyWrong:["Blocks are usually assumed not to interact with the factors; blocking is not meant to study shift.","","Runs are still randomized within each block.","Blocking uses up degrees of freedom; it does not add effects."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb049",phase:4,topic:"4.3.2",qtype:"missing-word",difficulty:1,stem:"Complete the rule of thumb for nuisance variables: “[?] what you can, randomize what you cannot.”",options:["Replicate","Measure","Eliminate","Block"],answer:3,hint:"Known & controllable nuisance → block; unknown or uncontrollable → randomize.",steps:[{title:"Key idea",body:"Known nuisance sources (shift, site, day, batch) are handled by **blocking**. Unknown ones are handled by **randomization**."},{title:"Apply",body:"Block by data-centre site, randomize run order within each site."}],final:"Block → answer **D**",whyWrong:["Replication estimates error; it does not deal with a specific known nuisance variable.","Measuring a nuisance variable (covariate) can help, but the rule is about blocking.","Some nuisance variables cannot be eliminated; the rule tells you how to design around them.",""],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb050",phase:4,topic:"4.3.2",qtype:"concept",difficulty:1,stem:"What is the main purpose of **replication** in a designed experiment?",options:["To protect against lurking variables that drift over time","To remove the effect of a known nuisance variable","To estimate the pure experimental error and make effect estimates more precise","To test more factors in the same number of runs"],answer:2,hint:"Replication → estimate of σ (pure error) + smaller standard error of effects.",steps:[{title:"Key idea",body:"Independent replicates show how much Y varies when nothing is changed. That **pure error** is the yardstick for judging whether effects are real."},{title:"Bonus",body:"More replicates also shrink the standard error of each effect."}],final:"Estimate error, improve precision → answer **C**",whyWrong:["That is the role of randomization.","That is the role of blocking.","","That is the role of fractional designs."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb051",phase:4,topic:"4.3.2",qtype:"scenario",difficulty:2,stem:"A test engineer runs a $2^3$ experiment on router throughput in **standard order** from 08:00 to 17:00. Lab temperature rises steadily during the day, and factor C changes only once (runs 5–8). What is the main risk?",options:["There is no risk because the design is orthogonal","The interactions cannot be estimated in standard order","Factor A will be most affected because it changes most often","The effect of C is confounded with the temperature drift, so a false or distorted C effect may appear"],answer:3,hint:"In standard order the slowest-changing column (last factor) is confounded with time → randomize.",steps:[{title:"Key idea",body:"In standard order factor C is low for the morning runs and high for the afternoon runs. Anything that changes with time looks like a C effect."},{title:"Fix",body:"Randomize the run order (and/or block by time of day)."}],final:"C confounded with time drift → answer **D**",whyWrong:["Orthogonality holds among the factors; it does not protect against an outside variable that tracks the run order.","All interactions can still be calculated; the problem is bias from the drift.","A alternates every run, so the drift largely cancels for A; C changes once, so it absorbs the drift.",""],trap:"Standard (Yates) order is for writing the design, not for running it.",bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb052",phase:4,topic:"4.3.2",qtype:"scenario",difficulty:2,stem:"One factor in a server-cooling experiment is the **chilled-water set-point**, which takes **4 hours** to stabilize after each change. The other three factors can be changed in minutes. Which experimental approach fits best?",options:["Run the design in standard order to minimize set-point changes, and analyze it as fully randomized","Leave the set-point out of the experiment","A split-plot design: set the hard-to-change factor for a group of runs and randomize the easy factors within it","Use one-factor-at-a-time testing"],answer:2,hint:"Hard-to-change factor → restricted randomization → split-plot design and analysis.",steps:[{title:"Key idea",body:"When one factor is hard or costly to reset, full randomization is impractical. A **split-plot** design randomizes the hard factor at the whole-plot level and the easy factors within each whole plot."},{title:"Analysis",body:"The analysis must use the correct (whole-plot and sub-plot) error terms."}],final:"Split-plot design → answer **C**",whyWrong:["Restricting randomization but analyzing as if fully randomized gives wrong error terms and misleading p-values.","The set-point may be a vital X; dropping it loses the information the team needs.","","OFAT does not solve the hard-to-change problem and misses interactions."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb053",phase:4,topic:"4.3.2",qtype:"concept",difficulty:2,stem:"Which statement about **one-factor-at-a-time (OFAT)** experimentation is correct?",options:["It is the most efficient way to estimate interactions","It cannot detect interactions and may miss the true best combination of settings","It uses every run to estimate every effect","It always finds the optimum if each factor is optimized in turn"],answer:1,hint:"OFAT: blind to interactions, poor precision per run, risk of false optimum.",steps:[{title:"Key idea",body:"OFAT changes one X while the others stay at baseline. If the best level of A depends on B, OFAT can never see it."},{title:"Contrast",body:"A factorial changes factors together in a balanced pattern, so it captures interactions with fewer total runs per unit of information."}],final:"OFAT misses interactions → answer **B**",whyWrong:["OFAT holds other factors fixed, so interactions cannot be estimated at all.","","That is a property of factorial designs (hidden replication).","With interactions, optimizing factors one at a time can stop at a false optimum."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb054",phase:4,topic:"4.3.2",qtype:"concept",difficulty:2,stem:"Which experimental method is designed to find settings that make a product or process **robust to noise**, using inner and outer arrays and signal-to-noise ratios?",options:["Taguchi (robust parameter design)","Plackett–Burman screening","Evolutionary operation (EVOP)","Mixture design"],answer:0,hint:"Taguchi: control factors in the inner array, noise factors in the outer array, analyze S/N ratio.",steps:[{title:"Key idea",body:"Taguchi methods cross an **inner array** of control factors with an **outer array** of noise factors, then choose control settings that maximize a **signal-to-noise ratio**."},{title:"Use",body:"The goal is low variation in Y despite noise, as well as being on target."}],final:"Taguchi methods → answer **A**",whyWrong:["","Plackett–Burman designs screen many main effects; they do not use outer noise arrays.","EVOP makes small ongoing changes to a live process to drift towards better settings.","Mixture designs handle components whose proportions must sum to 100%."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb055",phase:4,topic:"4.3.2",qtype:"concept",difficulty:1,stem:"What is a **Plackett–Burman** design mainly used for?",options:["Fitting a full quadratic model to find an optimum","Screening many factors for main effects with very few runs","Estimating all two-factor interactions without aliasing","Studying mixtures whose proportions must add to 100%"],answer:1,hint:"Plackett–Burman = two-level screening, N a multiple of 4, up to N − 1 factors, Resolution III.",steps:[{title:"Key idea",body:"Plackett–Burman designs give run sizes of 12, 20, 24, 28 … (not only powers of 2) and estimate main effects for up to N − 1 factors."},{title:"Limitation",body:"They assume interactions are negligible, so they are for screening only."}],final:"Screening main effects → answer **B**",whyWrong:["That needs a response-surface design such as a CCD or Box–Behnken.","","Plackett–Burman designs are Resolution III; two-factor interactions are partially aliased with main effects.","That is a mixture design."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb056",phase:4,topic:"4.3.2",qtype:"concept",difficulty:2,stem:"An operator wants to tune a **live** core network gradually, making only **small** changes to two parameters during normal operation, and moving towards better performance over weeks. Which method fits?",options:["Evolutionary operation (EVOP)","A Resolution III screening design","A central composite design run in the lab","A Taguchi outer array"],answer:0,hint:"EVOP = small, repeated factorial changes in the live process; effects build up evidence over many cycles.",steps:[{title:"Key idea",body:"**EVOP** runs a small two-level factorial (often with a center point) again and again in normal operation. The changes are small enough not to harm output."},{title:"Use",body:"It suits processes that cannot be taken offline for a large experiment."}],final:"EVOP → answer **A**",whyWrong:["","Screening uses bold level changes in a dedicated test; EVOP uses small changes in normal production.","A CCD is run as a dedicated experiment, not as small continuous changes in live service.","An outer array varies noise factors; it is not a method for gradual live tuning."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb057",phase:4,topic:"4.3.2",qtype:"concept",difficulty:2,stem:"A contact centre wants to find the best split of agent time across **voice, chat and email**, where the three shares must always add up to **100%**. Which design type is appropriate?",options:["A $2^3$ full factorial","A Plackett–Burman design","A split-plot design","A mixture design"],answer:3,hint:"Components that are proportions of a whole (sum = 1) → mixture design (e.g. simplex lattice).",steps:[{title:"Key idea",body:"In a **mixture** experiment the response depends on the proportions of components, and the proportions are constrained to sum to 1."},{title:"Apply",body:"Increasing the chat share must reduce voice and/or email, so a factorial cannot be used."}],final:"Mixture design → answer **D**",whyWrong:["In a factorial each factor is set independently; here the shares are not independent because they must sum to 100%.","Plackett–Burman designs screen independent factors.","Split-plot designs handle hard-to-change factors, not proportions that sum to a constant.",""],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb058",phase:4,topic:"4.3.2",qtype:"concept",difficulty:2,stem:"Which designs are used in **response surface methodology (RSM)** to fit curvature and find an optimum?",options:["Plackett–Burman and Resolution III fractional factorials","Two-level full factorials without center points","Central composite and Box–Behnken designs","Paired t-tests and one-way ANOVA"],answer:2,hint:"RSM needs at least 3 levels per factor: CCD (cube + axial + center) or Box–Behnken (edge midpoints + center).",steps:[{title:"Key idea",body:"A response surface model includes squared terms ($x_i^2$). Estimating them needs more than two levels per factor."},{title:"Designs",body:"A **central composite design** adds axial and center points to a factorial; a **Box–Behnken** design uses edge midpoints and center points."}],final:"CCD and Box–Behnken → answer **C**",whyWrong:["These are screening designs that estimate only linear main effects.","Two levels cannot estimate squared terms.","","These are hypothesis tests, not designs for fitting response surfaces."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb059",phase:4,topic:"4.3.2",qtype:"not-except",difficulty:2,stem:"All of the following help control **nuisance** variation in an experiment EXCEPT:",options:["Running the design in standard (Yates) order","Randomizing the run order","Blocking on a known nuisance source such as shift","Recording a measurable nuisance variable as a covariate"],answer:0,hint:"Tools for nuisance: randomize, block, hold constant, measure as covariate.",steps:[{title:"Key idea",body:"Nuisance variables are handled by holding them constant, **blocking**, **randomizing** or measuring them as **covariates**."},{title:"Odd one out",body:"Standard order is a systematic order. It makes slowly changing factors line up with time, which increases the risk from nuisance drift."}],final:"Standard order does not help → answer **A**",whyWrong:["","Randomization protects against unknown nuisance variables.","Blocking removes known nuisance variation.","A covariate (e.g. outdoor temperature) can be adjusted for in the analysis."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb060",phase:4,topic:"4.3.2",qtype:"true-false",difficulty:2,stem:"True or false: when an experiment is run in blocks, the block factor is normally assumed **not** to interact with the experimental factors.",options:["True","False"],answer:0,hint:"Blocks shift the level of Y; they are not studied for interactions.",steps:[{title:"Key idea",body:"A blocking factor is a nuisance, not a factor of interest. The standard analysis assumes it adds a constant shift to every run in the block."},{title:"Consequence",body:"If a strong block × factor interaction is suspected (e.g. a factor works only on one site), the site should be treated as a real factor instead."}],final:"True → answer **True**",whyWrong:["","Blocking assumes the block shifts all responses equally; block × factor interactions are usually assumed to be zero and are pooled into error."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb061",phase:4,topic:"4.3.2",qtype:"true-false",difficulty:1,stem:"True or false: a one-factor-at-a-time (OFAT) study can estimate interactions as long as each factor is tested at both of its levels.",options:["True","False"],answer:1,hint:"Interactions need runs where factors change together.",steps:[{title:"Key idea",body:"To estimate AB you need A’s effect at both levels of B. OFAT measures A’s effect only at B’s baseline level."},{title:"Conclusion",body:"Only factorial-type designs estimate interactions."}],final:"False → answer **False**",whyWrong:["OFAT never changes two factors together from the baseline, so the combinations needed to estimate an interaction are never run.",""],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb062",phase:4,topic:"4.3.2",qtype:"scenario",difficulty:2,stem:"A Black Belt runs an experiment on order-handling time across **two sites** (Muscat and Sohar). Sites differ in staff experience, but site is not a factor of interest. What is the BEST design choice?",options:["Run all high-level settings in Muscat and all low-level settings in Sohar","Ignore site and pool all runs into one random order","Treat site as a block: run a balanced set of treatments at each site and randomize within each site","Drop Sohar and run everything in Muscat"],answer:2,hint:"Known nuisance (site, shift, day) → block with balanced treatments in each block.",steps:[{title:"Key idea",body:"Site is a known nuisance source. Putting a balanced set of treatment combinations at each site lets the analysis remove the site-to-site difference."},{title:"Within blocks",body:"Run order is still randomized inside each site."}],final:"Block by site → answer **C**",whyWrong:["That confounds every factor with site; the effects cannot be separated from the site difference.","This is valid but the site difference inflates the error and hides real effects.","","Possible, but conclusions would apply to one site only; blocking keeps both sites and removes the difference."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb063",phase:4,topic:"4.3.2",qtype:"best-action",difficulty:2,stem:"During an experiment on call-handling time, the outdoor temperature (which affects cooling and system latency) cannot be controlled or blocked, but it **can be measured** for every run. What is the BEST approach?",options:["Ignore it because randomization removes all nuisance effects","Record the temperature for each run and include it as a covariate in the analysis","Stop the experiment until the temperature is constant","Add temperature as a third factor at two levels"],answer:1,hint:"Measurable but uncontrollable nuisance → covariate (analysis of covariance).",steps:[{title:"Key idea",body:"A **covariate** is a measured nuisance variable. Including it in the model removes its contribution from the error term."},{title:"Apply",body:"Randomize the runs as planned and log temperature with each result."}],final:"Use a covariate → answer **B**",whyWrong:["Randomization prevents bias, but the temperature still adds noise; measuring it lets you remove that noise.","","That may never happen; the experiment can proceed if the temperature is recorded.","It cannot be set to chosen levels, so it cannot be a design factor."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb064",phase:4,topic:"4.3.2",qtype:"concept",difficulty:1,stem:"A product team compares two versions of the self-care app login screen by randomly assigning users to **version A** or **version B** and comparing completion rates. In DOE terms this is:",options:["A $2^2$ factorial","An observational study","A response surface design","A single-factor experiment with two levels (an A/B test)"],answer:3,hint:"A/B test = one factor, two levels, randomized assignment.",steps:[{title:"Key idea",body:"An **A/B test** is the simplest comparative experiment: one factor (version), two levels, random assignment of units."},{title:"Analysis",body:"A two-proportion test (or 2-sample t for a continuous Y) analyzes it."}],final:"One factor, two levels → answer **D**",whyWrong:["There is only one factor (screen version), with two levels.","The team assigns users at random, so it is an experiment, not passive observation.","There is no continuous factor with three or more levels and no curvature to model.",""],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb065",phase:4,topic:"4.3.2",qtype:"concept",difficulty:2,stem:"Why are two-level designs usually preferred to three-level full factorials in the early stages of experimentation?",options:["Three-level designs cannot be randomized","Two-level designs estimate squared terms more precisely","Three-level designs cannot estimate interactions","They need far fewer runs, and curvature can still be checked by adding center points"],answer:3,hint:"$2^k$ vs $3^k$: 32 vs 243 runs for k = 5; center points test curvature cheaply.",steps:[{title:"Key idea",body:"A $3^k$ design grows very fast. Two-level designs are economical and give main effects and interactions."},{title:"Curvature",body:"A few center points detect curvature; if it is found, axial points can be added later to build a CCD."}],final:"Fewer runs + center points → answer **D**",whyWrong:["Any design can be randomized.","Two-level designs cannot estimate squared terms at all.","Three-level factorials do estimate interactions; they are just expensive.",""],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb066",phase:4,topic:"4.3.2",qtype:"concept",difficulty:2,stem:"What is the main weakness of **trial-and-error** (“change something and see”) experimentation?",options:["Changes are unplanned, so effects cannot be separated, interactions are missed and results are hard to reproduce","It always takes more runs than a full factorial","It cannot be used on IT systems","It requires advanced statistical software"],answer:0,hint:"Unplanned changes → confounded effects, no error estimate, no model.",steps:[{title:"Key idea",body:"Trial and error changes several things at once in no fixed pattern and rarely replicates. You may find something that works, but you will not know why."},{title:"DOE answer",body:"A planned, balanced design separates effects and estimates error."}],final:"Effects cannot be separated → answer **A**",whyWrong:["","It may take few or many runs; the problem is the quality of the information, not only the count.","It is used everywhere; that is not its weakness.","Trial and error needs no statistics, which is part of the problem."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb067",phase:4,topic:"4.3.2",qtype:"statements",difficulty:2,stem:`Which statements about experimental methods are correct?

1. A full factorial estimates all main effects and interactions without aliasing.
2. A fractional factorial runs a planned subset of a full factorial.
3. Box–Behnken designs are mainly used for screening many factors.
4. Split-plot designs handle factors that are hard to change.`,options:["1 and 3 only","1, 2 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],answer:1,hint:"Full = no aliasing; fractional = subset; BBD = RSM; split-plot = hard-to-change factors.",steps:[{title:"Check each",body:"1 True. 2 True — a planned subset that keeps balance and orthogonality. 3 False — Box–Behnken is a response-surface design for a few vital factors. 4 True."},{title:"Decide",body:"Statements 1, 2 and 4."}],final:"1, 2, 4 → answer **B**",whyWrong:["Statement 3 is false (Box–Behnken is an RSM design), and statements 2 and 4 are true.","","Statement 3 is false, and statement 1 is true.","Statement 3 is false: Box–Behnken designs are used to fit quadratic models for optimization."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb068",phase:4,topic:"4.3.2",qtype:"best-action",difficulty:3,stem:"A team plans a $2^4$ experiment on billing-run time. The four factors can be changed easily, but test runs are only possible on **4 nights**, and each night the database cache is reset, which may shift run times. What is the BEST plan?",options:["Run nights 1–2 with factor A low and nights 3–4 with A high","Ignore the nights and randomize all 16 runs as one block","Run 4 runs per night as a blocked design that confounds chosen interactions (never main effects) with nights, and randomize within each night","Run only one night to avoid the cache problem"],answer:2,hint:"Blocking a $2^k$: confound the highest-order interaction(s) with blocks; randomize within blocks.",steps:[{title:"Key idea",body:"With 16 runs and 4 nights, each night is a block of 4 runs. The design generators are chosen so that the blocks are confounded only with high-order interactions that are assumed negligible."},{title:"Apply",body:"Four blocks need two block generators, and their product is also confounded. For example ABC and ACD also confound their product BD. Main effects stay clear of the nights, and run order is randomized each night."},{title:"Trade-off",body:"With 4 blocks of 4 runs, at least one two-factor interaction must be given up to the blocks, so choose one that process knowledge says is unlikely."}],final:"Block by night, randomize within → answer **C**",whyWrong:["This confounds A with the night effect, so the A effect cannot be separated from cache differences.","Randomization avoids bias, but the night-to-night shift is added to the error and weakens the test.","","One night may not allow all 16 runs, and the results would be specific to that night."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb069",phase:4,topic:"4.3.2",qtype:"best-action",difficulty:2,stem:"In a $2^3$ experiment on DNS response time, the engineer sets up each treatment once and records the response time of **three consecutive queries**, then analyzes the 24 values as if there were 3 replicates. What is the BEST correction?",options:["Keep the analysis as it is; 24 values give more degrees of freedom","Drop two of the three readings at random","Treat the three readings as repeats (average them per run) and add true replicates by setting each treatment up again independently","Switch to a Plackett–Burman design"],answer:2,hint:"Repeats (same set-up) ≠ replicates (independent set-ups). Only replicates estimate pure error.",steps:[{title:"Key idea",body:"Readings taken from one set-up miss the set-up-to-set-up variation, so the error term is too small (**pseudo-replication**)."},{title:"Fix",body:"Average the repeated readings to one value per run, and replicate by resetting and re-running each treatment in random order."}],final:"Average repeats; add true replicates → answer **C**",whyWrong:["Consecutive readings from one set-up are not independent; using them as replicates understates error and inflates significance.","This throws data away and still leaves no estimate of run-to-run error.","","The design type is not the problem; the error estimate is."],trap:"Pseudo-replication makes effects look more significant than they are.",bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb070",phase:4,topic:"4.3.2",qtype:"scenario",difficulty:2,stem:"A Black Belt has **four** vital factors for SMS delivery latency, needs to see **all two-factor interactions** clearly, and can afford about **20 runs**. Which method fits best?",options:["A 12-run Plackett–Burman design","A $2^4$ full factorial (16 runs), using the spare runs as center points","A $2^{4-1}$ half fraction (8 runs)","One-factor-at-a-time testing (5 runs)"],answer:1,hint:"Few factors + interactions needed + budget allows → full factorial.",steps:[{title:"Key idea",body:"With 4 factors a full factorial costs only 16 runs and estimates every main effect and interaction without aliasing."},{title:"Use the remainder",body:"The extra 4 runs can be center points to check curvature and estimate pure error."}],final:"Full $2^4$ + center points → answer **B**",whyWrong:["Plackett–Burman designs alias main effects with two-factor interactions; they cannot show interactions clearly.","","With only 8 runs, pairs of two-factor interactions are aliased with each other (AB = CD).","OFAT cannot estimate interactions."],bookRef:"Syllabus 4.3.2"},{id:"sv-4-bb071",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:1,stem:"A Black Belt plans a $2^3$ factorial on **router firmware upgrade time** with **2 replicates** of the corner points and **4 center points**. How many runs must be scheduled?",options:["16","48","12","20"],answer:3,hint:"Total runs = (2^k × replicates) + center points.",steps:[{title:"Given",body:"k = 3, r = 2, center points $n_c$ = 4."},{title:"Formula",body:"$$N=2^k\\times r+n_c$$"},{title:"Substitute",body:"$$N=2^3\\times 2+4=16+4$$"},{title:"Compute",body:"N = **20** runs."}],final:"N = 20 → answer **D**",whyWrong:["The center points were left out of the total.","The center points were treated like extra replicates of every corner run; they are single runs at the middle of the design.","Only one replicate of the factorial was counted.",""],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb072",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:2,stem:"A Black Belt plans a $2^4$ factorial on **fibre-splice insertion loss** with **2 replicates** of the corner points and **3 center points**. How many runs must be scheduled?",options:["35","32","80","19"],answer:0,hint:"Total runs = (2^k × replicates) + center points.",steps:[{title:"Given",body:"k = 4, r = 2, center points $n_c$ = 3."},{title:"Formula",body:"$$N=2^k\\times r+n_c$$"},{title:"Substitute",body:"$$N=2^4\\times 2+3=32+3$$"},{title:"Compute",body:"N = **35** runs."}],final:"N = 35 → answer **A**",whyWrong:["","The center points were left out of the total.","The center points were treated like extra replicates of every corner run; they are single runs at the middle of the design.","Only one replicate of the factorial was counted."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb073",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:2,stem:"A Black Belt plans a $2^5$ factorial on **API gateway latency** with **1 replicate** of the corner points and **6 center points**. How many runs must be scheduled?",options:["32","224","16","38"],answer:3,hint:"Total runs = (2^k × replicates) + center points.",steps:[{title:"Given",body:"k = 5, r = 1, center points $n_c$ = 6."},{title:"Formula",body:"$$N=2^k\\times r+n_c$$"},{title:"Substitute",body:"$$N=2^5\\times 1+6=32+6$$"},{title:"Compute",body:"N = **38** runs."}],final:"N = 38 → answer **D**",whyWrong:["The center points were left out of the total.","The center points were treated like extra replicates of every corner run; they are single runs at the middle of the design.","The factorial part was taken as 2k instead of $2^k$.",""],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb074",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:2,stem:"A $2^3$ full factorial on **VoIP MOS score** is run with **2 replicates** and no center points. If the full model (all main effects and interactions) is fitted, how many degrees of freedom are left for **error**?",options:["8","15","12","1"],answer:0,hint:"Error df = total runs − number of model terms (including the constant). For a full $2^k$ model that is N − $2^k$.",steps:[{title:"Given",body:"$N=2^3\\times 2=16$ runs; the full model has $2^3$ = 8 terms (constant + 7 effects)."},{title:"Formula",body:"$$df_{error}=N-2^k=2^k(r-1)$$"},{title:"Compute",body:"$$df_{error}=16-8=8\\times(2-1)=8$$"},{title:"Why it matters",body:"With one replicate there would be 0 error df, so p-values could not be computed without pooling terms or adding center points."}],final:"df(error) = 8 → answer **A**",whyWrong:["","This is the total degrees of freedom, before the model terms are removed.","Only the main effects were subtracted; the full model also includes every interaction.","This is the error df for a single treatment combination, not for the whole design."],trap:"An unreplicated $2^k$ full model has zero error degrees of freedom.",bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb075",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:3,stem:"A $2^4$ full factorial on **provisioning lead time** is run with **3 replicates** and no center points. If the full model (all main effects and interactions) is fitted, how many degrees of freedom are left for **error**?",options:["47","32","43","2"],answer:1,hint:"Error df = total runs − number of model terms (including the constant). For a full $2^k$ model that is N − $2^k$.",steps:[{title:"Given",body:"$N=2^4\\times 3=48$ runs; the full model has $2^4$ = 16 terms (constant + 15 effects)."},{title:"Formula",body:"$$df_{error}=N-2^k=2^k(r-1)$$"},{title:"Compute",body:"$$df_{error}=48-16=16\\times(3-1)=32$$"},{title:"Why it matters",body:"With one replicate there would be 0 error df, so p-values could not be computed without pooling terms or adding center points."}],final:"df(error) = 32 → answer **B**",whyWrong:["This is the total degrees of freedom, before the model terms are removed.","","Only the main effects were subtracted; the full model also includes every interaction.","This is the error df for a single treatment combination, not for the whole design."],trap:"An unreplicated $2^k$ full model has zero error degrees of freedom.",bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb076",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:2,stem:"A $2^4$ design with **2 replicates** and **4 center points** is planned on a live-like test bed. Each run takes **45 minutes** (including reset) and the lab is available **6 hours per day**. How many lab days are needed?",options:["4.5","4","5","2"],answer:2,hint:"Days = ceiling(total runs × time per run ÷ available time per day).",steps:[{title:"Given",body:"Runs = $2^4\\times 2+4=36$; 45 min per run; window = 6 h = 360 min."},{title:"Total time",body:"$$36\\times 45=1620\\text{ min}$$"},{title:"Days",body:"$$\\dfrac{1620}{360}=4.50\\Rightarrow 5\\text{ days}$$"},{title:"Planning point",body:"If runs span several days, consider blocking by day so that day-to-day shifts do not inflate the error."}],final:"5 days → answer **C**",whyWrong:["The answer was not rounded up; a partial day still needs to be booked.","The 4 center points were not included.","","The full 24-hour day was used instead of the 6-hour lab window."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb077",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:1,stem:"Each run of a drive-test experiment on 4G coverage costs **120 OMR** (vehicle, engineer and fuel). The plan is a $2^3$ factorial with **3 replicates**. What is the total cost?",options:["960 OMR","1,080 OMR","2,880 OMR","2,160 OMR"],answer:2,hint:"Cost = runs × cost per run; runs = 2^k × replicates.",steps:[{title:"Given",body:"$N=2^3\\times 3=24$ runs; 120 OMR per run."},{title:"Compute",body:"$$\\text{Cost}=24\\times 120=2,880\\text{ OMR}$$"},{title:"Planning point",body:"Cost and time often decide between a full factorial, a fraction or fewer replicates."}],final:"2,880 OMR → answer **C**",whyWrong:["Only one replicate was costed.","The runs were taken as k × r = 9 instead of $2^k\\times r$ = 24.","","The runs were taken as 2 × k × r = 18; the factorial part is $2^3$ = 8, not 2 × 3."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb078",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:2,stem:"Past data show the run-to-run standard deviation of **page-load time** is **σ = 6 ms**. A two-level factorial with **N = 16 runs** in total is planned. What is the standard error of each estimated effect?",options:["1.50 ms","3.00 ms","0.75 ms","2.12 ms"],answer:1,hint:"For a two-level design, SE(effect) = 2σ ÷ √N (effect = difference of two averages of N/2 runs each).",steps:[{title:"Given",body:"σ = 6 ms, N = 16."},{title:"Formula",body:"$$SE(E)=\\sqrt{\\dfrac{\\sigma^2}{\\tfrac{N}{2}}+\\dfrac{\\sigma^2}{\\tfrac{N}{2}}}=\\dfrac{2\\sigma}{\\sqrt{N}}$$"},{title:"Compute",body:"$$SE(E)=\\dfrac{2\\times 6}{\\sqrt{16}}=\\dfrac{12}{4.000}=3.00\\text{ ms}$$"},{title:"Use",body:"An effect needs to be roughly 2 or more standard errors to be detected reliably, so σ and N together decide how small an effect the design can see."}],final:"SE = 3.00 ms → answer **B**",whyWrong:["This is σ ÷ √N, the standard error of the coded coefficient (half the effect), not of the effect.","","N was not square-rooted.","This treats the effect like a difference of two means of N runs each; each average uses only N ÷ 2 runs."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb079",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:2,stem:"Past data show the run-to-run standard deviation of **page-load time** is **σ = 3 ms**. A two-level factorial with **N = 32 runs** in total is planned. What is the standard error of each estimated effect?",options:["0.53 ms","0.19 ms","0.75 ms","1.06 ms"],answer:3,hint:"For a two-level design, SE(effect) = 2σ ÷ √N (effect = difference of two averages of N/2 runs each).",steps:[{title:"Given",body:"σ = 3 ms, N = 32."},{title:"Formula",body:"$$SE(E)=\\sqrt{\\dfrac{\\sigma^2}{\\tfrac{N}{2}}+\\dfrac{\\sigma^2}{\\tfrac{N}{2}}}=\\dfrac{2\\sigma}{\\sqrt{N}}$$"},{title:"Compute",body:"$$SE(E)=\\dfrac{2\\times 3}{\\sqrt{32}}=\\dfrac{6}{5.657}=1.06\\text{ ms}$$"},{title:"Use",body:"An effect needs to be roughly 2 or more standard errors to be detected reliably, so σ and N together decide how small an effect the design can see."}],final:"SE = 1.06 ms → answer **D**",whyWrong:["This is σ ÷ √N, the standard error of the coded coefficient (half the effect), not of the effect.","N was not square-rooted.","This treats the effect like a difference of two means of N runs each; each average uses only N ÷ 2 runs.",""],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb080",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:3,stem:"For a $2^3$ experiment on **call handle time**, σ ≈ 5 s. The team wants the standard error of each effect to be **no more than 1.5 s**. Using SE(effect) = 2σ ÷ √N, how many **replicates** are needed?",options:["6","45","5","2"],answer:0,hint:"Rearrange SE = 2σ ÷ √N to N ≥ (2σ ÷ SE)², then replicates = ceiling(N ÷ 2^k).",steps:[{title:"Given",body:"σ = 5, target SE = 1.5, one replicate = $2^3$ = 8 runs."},{title:"Rearrange",body:"$$N\\ge\\left(\\dfrac{2\\sigma}{SE}\\right)^2$$"},{title:"Compute N",body:"$$N\\ge\\left(\\dfrac{2\\times 5}{1.5}\\right)^2=44.4$$"},{title:"Replicates",body:"$$r=\\left\\lceil\\dfrac{44.4}{8}\\right\\rceil=6\\quad(N=48)$$"}],final:"r = 6 → answer **A**",whyWrong:["","This is the minimum number of runs N, not the number of replicates of the 8-run design.","Rounding down gives N = 40, so the standard error would be above the target.","The factor 2 in SE = 2σ ÷ √N was dropped."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb081",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:2,stem:"Before a DOE on **optical power at the ONT (dBm)**, a Gage R&R gives σ(measurement) = **0.5 dB** and σ(total) = **2 dB**. What is the %Study Variation, and what does it mean for the experiment?",options:["6.25% — acceptable; proceed with the DOE","25% — unacceptable; the DOE must be cancelled","400% — the meter is four times better than needed","25% — marginal; improve the meter if practical, because measurement noise will hide small effects"],answer:3,hint:"%Study Var = σ(MS) ÷ σ(total) × 100. Guide: < 10% good, 10–30% marginal, > 30% unacceptable.",steps:[{title:"Given",body:"σ(MS) = 0.5, σ(total) = 2."},{title:"Formula",body:"$$\\%SV=\\dfrac{\\sigma_{MS}}{\\sigma_{total}}\\times 100$$"},{title:"Compute",body:"$$\\%SV=\\dfrac{0.5}{2}\\times 100=25\\%$$"},{title:"Decide",body:"Marginal. Measurement noise adds to the experimental error, so more replicates would be needed to see the same effect. Improve the gauge if it is practical."}],final:"%SV = 25% (marginal) → answer **D**",whyWrong:["This is the %Contribution (variance ratio). %Study Variation uses the ratio of standard deviations.","Under the common AIAG guideline 10–30% is marginal, not automatically unacceptable.","The ratio was inverted (total ÷ measurement).",""],trap:"%Contribution (variance ratio) and %Study Variation (σ ratio) are different numbers for the same study.",bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb082",phase:4,topic:"4.3.3",qtype:"calculation",difficulty:1,stem:"A single-replicate $2^3$ design on **MPLS failover time** includes **5 center points**. How many degrees of freedom for **pure error** do the center points provide?",options:["5","4","12","0"],answer:1,hint:"Pure error df from n_c center points = n_c − 1.",steps:[{title:"Given",body:"$n_c$ = 5 center points, no other replicates."},{title:"Formula",body:"$$df_{PE}=n_c-1$$"},{title:"Compute",body:"$$df_{PE}=5-1=4$$ Their variance $s^2=\\dfrac{\\sum(y_i-\\bar y_c)^2}{n_c-1}$ estimates σ² without needing to replicate every corner."}],final:"df(pure error) = 4 → answer **B**",whyWrong:["The pure error df is the number of center points minus 1 (one df goes to their mean).","","This is the total df for all runs.","Replicated center points do give a pure error estimate, even when the corners are not replicated."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb083",phase:4,topic:"4.3.3",qtype:"concept",difficulty:2,stem:"How should the **levels** of a quantitative factor normally be chosen for a screening experiment?",options:["Far enough apart to produce a detectable effect, but within a range that is safe and operationally realistic","As close together as possible to avoid upsetting the process","At the extreme limits of what the equipment can physically do","At the current operating point only"],answer:0,hint:"“Bold but not reckless”: wide enough to see an effect, narrow enough to stay safe and relevant.",steps:[{title:"Key idea",body:"The size of an effect grows with the distance between levels. Too narrow → effect lost in noise. Too wide → risk of outages, nonlinear behaviour or irrelevant results."},{title:"Apply",body:"Use process knowledge and the operating window to set bold but realistic levels."}],final:"Bold but realistic levels → answer **A**",whyWrong:["","Levels that are too close produce effects smaller than the noise, so real X’s are missed.","Extremes may be unsafe, unrealistic or in a region where the response behaves differently.","A factor needs at least two different levels to have an effect estimated."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb084",phase:4,topic:"4.3.3",qtype:"best-action",difficulty:2,stem:"A team wants to test **interface MTU 9,000 bytes** as the high level on the **live** core network. An engineer warns this could cause packet drops and a customer outage on some links. What is the BEST action?",options:["Go ahead on the live network because bold levels are needed","Drop MTU size from the experiment","Run the experiment on a representative test bed or in a controlled maintenance window, or narrow the level to a safe value","Use the high level only on the replicate runs"],answer:2,hint:"Design considerations include safety, customer impact and operability of every factor level.",steps:[{title:"Key idea",body:"Each treatment combination must be **safe and feasible** to run. Risky levels need a test environment, a maintenance window or a narrower range."},{title:"Apply",body:"A test bed that mirrors production lets the team keep a bold level without customer risk."}],final:"Test safely or narrow the level → answer **C**",whyWrong:["Bold levels must still be safe; a customer outage is not an acceptable experimental cost.","MTU may be a vital X; removing it loses information. Find a safe way to test it instead.","","Every replicate must contain the same treatment combinations; changing levels between replicates breaks the design."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb085",phase:4,topic:"4.3.3",qtype:"best-action",difficulty:2,stem:"A Black Belt is about to start a DOE on **ticket resolution time**. A control chart of the last 8 weeks shows several out-of-control points from an unresolved system problem. What is the BEST action?",options:["Run the DOE now; randomization will handle the instability","Find and remove the special cause first so the process is stable during the experiment","Add more factors to the DOE to explain the out-of-control points","Run the DOE only on the days with out-of-control points"],answer:1,hint:"Experiment on a stable process: special causes add noise and bias.",steps:[{title:"Key idea",body:"A DOE compares treatments against background noise. If the process is jumping because of special causes, the noise is large and unpredictable, and effects can be masked or faked."},{title:"Apply",body:"Stabilize first (fix the system problem), then run the experiment."}],final:"Stabilize the process first → answer **B**",whyWrong:["Large special-cause shifts inflate the error and can be confused with factor effects even with randomization.","","The special cause is already known; it should be fixed, not added as a factor.","That would build the experiment on unstable data."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb086",phase:4,topic:"4.3.3",qtype:"concept",difficulty:1,stem:"Why must the **measurement system** for the response be checked before a designed experiment?",options:["Because the DOE analysis assumes the measurement system has zero variation","Because a Gage R&R is needed to choose the factor levels","Because DOE software will not run without an MSA","Measurement error adds to experimental error and can hide real effects or create false ones"],answer:3,hint:"Bad MSA → noisy or biased Y → weak or misleading DOE.",steps:[{title:"Key idea",body:"Every response value = true value + measurement error. Large measurement error inflates the error term, so real effects become non-significant. Bias can also shift results."},{title:"Apply",body:"Run Gage R&R or attribute agreement analysis first and fix the gauge if needed."}],final:"Measurement error masks effects → answer **D**",whyWrong:["No system has zero variation; it needs to be small relative to the effects of interest.","Levels are set from process knowledge, not from the Gage R&R.","Software does not check this; the experimenter must.",""],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb087",phase:4,topic:"4.3.3",qtype:"not-except",difficulty:2,stem:"All of the following are good practice when planning a DOE EXCEPT:",options:["Letting the operators choose the run order to suit their schedule","Holding factors that are not being studied at constant, documented settings","Running a short pilot to check that every treatment combination is feasible","Recording any unusual events that occur during each run"],answer:0,hint:"Run order should be randomized (or restricted by design), not chosen for convenience.",steps:[{title:"Key idea",body:"A convenience order tends to group similar settings together, which confounds factors with time and other drifting variables."},{title:"Good practice",body:"Hold other factors constant, run a pilot, log everything and randomize."}],final:"Convenience run order is not good practice → answer **A**",whyWrong:["","Holding other factors constant reduces noise and is good practice.","A pilot run catches practical problems early.","A run log helps explain outliers during analysis."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb088",phase:4,topic:"4.3.3",qtype:"concept",difficulty:2,stem:"Which factor type **cannot** use a true center point (a run at the midpoint of every factor)?",options:["A continuous factor such as buffer size in KB","A time setting such as a 30 s vs 60 s timeout","A categorical factor such as “vendor A vs vendor B”","A percentage such as 40% vs 60% CPU threshold"],answer:2,hint:"Center points need a numeric midpoint; categorical factors have none.",steps:[{title:"Key idea",body:"A center point sets every factor to the middle of its range. Categorical factors have no middle level."},{title:"Work-around",body:"With some categorical factors, center points can be run at the midpoint of the numeric factors for each level of the categorical ones."}],final:"Categorical factors have no center → answer **C**",whyWrong:["A continuous factor has a natural midpoint.","Time is continuous; 45 s is a valid midpoint.","","A percentage has a midpoint (50%)."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb089",phase:4,topic:"4.3.3",qtype:"concept",difficulty:2,stem:"Besides testing for curvature, what is another practical benefit of spreading center points throughout the run order?",options:["They show whether the process drifted during the experiment","They double the number of factors that can be estimated","They remove the need for randomization","They allow quadratic terms for each factor to be estimated separately"],answer:0,hint:"Center points: curvature check + pure error + stability check over time.",steps:[{title:"Key idea",body:"Center points are all run at the same settings. If their results trend over the experiment, something outside the design is changing."},{title:"Apply",body:"Place center points at the start, middle and end of the schedule."}],final:"Detect drift over time → answer **A**",whyWrong:["","Center points add no new factor columns.","The factorial runs still need to be randomized.","Center points detect overall curvature but cannot say which factor causes it."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb090",phase:4,topic:"4.3.3",qtype:"statements",difficulty:2,stem:`Which statements about **sample size** (number of runs) in a DOE are correct?

1. More replicates make smaller effects detectable.
2. A larger process σ requires more runs to detect the same effect.
3. The number of runs needed does not depend on the effect size the team wants to detect.
4. Unreplicated designs can still be analyzed by pooling negligible high-order interactions into error.`,options:["1 and 3 only","2 and 3 only","1, 2, 3 and 4","1, 2 and 4 only"],answer:3,hint:"Runs needed rise with σ, fall with effect size, and depend on α and power.",steps:[{title:"Check each",body:"1 True — SE of effects falls as N rises. 2 True — more noise needs more runs. 3 False — detecting a smaller effect needs more runs. 4 True — high-order interactions (or a normal/half-normal effects plot) provide an error estimate."},{title:"Decide",body:"Statements 1, 2 and 4."}],final:"1, 2, 4 → answer **D**",whyWrong:["Statement 3 is false and statements 2 and 4 are true.","Statement 3 is false; statements 1 and 4 are also true.","Statement 3 is false: the smaller the effect to detect, the more runs are needed.",""],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb091",phase:4,topic:"4.3.3",qtype:"concept",difficulty:1,stem:"Where should the candidate factors for a DOE in the Improve phase mainly come from?",options:["Whatever settings are easiest to change","A random selection from all possible process settings","The evidence from Analyze (e.g. hypothesis tests, regression, FMEA, cause-and-effect analysis) and process knowledge","The settings that the vendor recommends changing"],answer:2,hint:"Factors = likely X’s from Analyze + expert knowledge.",steps:[{title:"Key idea",body:"DOE is expensive, so it focuses on X’s that the earlier phases suggest are linked to Y."},{title:"Apply",body:"C&E matrix, FMEA, graphs and hypothesis tests narrow the list."}],final:"From Analyze evidence → answer **C**",whyWrong:["Ease of change matters for planning, but factors should be chosen because they may affect Y.","Random selection wastes runs on unlikely X’s.","","Vendor input may help, but it is not a substitute for evidence about Y."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb092",phase:4,topic:"4.3.3",qtype:"scenario",difficulty:2,stem:"A DOE on **chatbot containment rate** has three factors. One factor (knowledge-base version) can only be changed by a vendor release, which takes **one week**. The other two factors change instantly. What design consideration applies?",options:["Nothing special; randomize all runs as usual","Randomization is restricted for the hard-to-change factor, so a split-plot structure and analysis are needed","The hard-to-change factor must be removed from the study","Run the hard-to-change factor at only one level"],answer:1,hint:"Hard-to-change factors → restricted randomization → split-plot.",steps:[{title:"Key idea",body:"Group the runs by knowledge-base version (whole plots) and randomize the two easy factors within each group."},{title:"Analysis",body:"The hard factor’s effect is tested against whole-plot error, which has fewer df, so it is detected less precisely."}],final:"Split-plot for the hard-to-change factor → answer **B**",whyWrong:["Fully randomizing would require a vendor release for many runs, which is impractical.","","It may be a key X; the design should accommodate it rather than drop it.","Then its effect cannot be estimated."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb093",phase:4,topic:"4.3.3",qtype:"concept",difficulty:2,stem:"Why might a team measure **more than one response** in the same experiment (e.g. throughput, latency and CPU load)?",options:["Because the analysis requires at least three responses","To increase the degrees of freedom for error","Settings that improve one CTQ may harm another, so trade-offs can be seen and balanced","Because each response doubles the number of factors"],answer:2,hint:"Multiple CTQs → watch for conflicts; optimize jointly (e.g. desirability).",steps:[{title:"Key idea",body:"Extra responses usually cost little because the runs are already being made. They reveal side-effects, such as higher CPU load when throughput rises."},{title:"Use",body:"Optimize jointly, for example with a desirability function."}],final:"See trade-offs between CTQs → answer **C**",whyWrong:["One response is enough for a valid analysis.","Error df depends on runs and model terms, not on how many responses are measured.","","Responses do not change the factor count."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb094",phase:4,topic:"4.3.3",qtype:"best-action",difficulty:2,stem:"Half-way through a randomized DOE on **backup job duration**, a storage firmware update is pushed to the test environment without warning. What is the BEST action?",options:["Ignore it because the run order was randomized","Record the event, check the center points or repeat runs before and after it, and treat the change as a block (or re-run affected runs) if it shifted results","Discard the whole experiment and start again","Delete the runs made after the update"],answer:1,hint:"Log unplanned events; test their impact; model as a block or re-run if needed.",steps:[{title:"Key idea",body:"An unplanned change is a new nuisance variable. Compare runs at the same settings (e.g. center points) before and after it."},{title:"Decide",body:"If there is a shift, add a block term (before/after) or re-run the affected treatments."}],final:"Log, check, block or re-run → answer **B**",whyWrong:["Randomization helps, but a known step change is better handled explicitly than left in the error.","","This may be unnecessary; the event can often be modelled as a block.","Deleting runs unbalances the design and loses information."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb095",phase:4,topic:"4.3.3",qtype:"true-false",difficulty:2,stem:"True or false: in a DOE, factors that are not being studied should be allowed to vary freely so that the results apply to all conditions.",options:["True","False"],answer:1,hint:"Hold non-studied factors constant, block, or randomize — do not ignore them.",steps:[{title:"Key idea",body:"Letting other X’s wander inflates the error term and can create false effects if they happen to line up with a factor."},{title:"Good practice",body:"Hold them constant and record the settings. If wider applicability is needed, include them as factors or blocks deliberately."}],final:"False → answer **False**",whyWrong:["Uncontrolled factors add noise and may bias the effects; they should be held constant (and documented) or blocked.",""],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb096",phase:4,topic:"4.3.3",qtype:"true-false",difficulty:1,stem:"True or false: a pilot (trial) run before the main experiment helps find practical problems, such as settings that cannot be achieved or data that are not recorded correctly.",options:["True","False"],answer:0,hint:"Pilot runs de-risk the main experiment.",steps:[{title:"Key idea",body:"A pilot checks that each treatment combination can be set, that the response is captured, and how long a run takes."},{title:"Benefit",body:"Problems are found before they spoil the real runs."}],final:"True → answer **True**",whyWrong:["","This is exactly why pilot runs are recommended."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb097",phase:4,topic:"4.3.3",qtype:"sequence",difficulty:2,stem:`Put these practical preparation steps for an experiment in a sensible order:

P. Confirm the measurement system is adequate
Q. Agree objective, response and factor levels with the process owner
R. Create a randomized run sheet and a data-collection form
S. Run a short pilot of a few treatment combinations`,options:["R → Q → P → S","P → R → Q → S","Q → R → S → P","Q → P → R → S"],answer:3,hint:"Agree what → confirm you can measure it → prepare the run sheet → pilot → full experiment.",steps:[{title:"Key idea",body:"Each step depends on the one before: the response defines what to measure, the factors define the run sheet, and the pilot tests the whole package."},{title:"Decide",body:"Q → P → R → S, then the main runs."}],final:"Q → P → R → S → answer **D**",whyWrong:["The run sheet cannot be created before the factors and levels are agreed.","The objective and response must be agreed before checking the gauge that measures that response.","The measurement system should be confirmed before any data, including pilot data, is collected.",""],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb098",phase:4,topic:"4.3.3",qtype:"scenario",difficulty:3,stem:"An experiment on **NOC alarm triage time** gives **no significant effects**, even though engineers are confident that two factors matter. The levels used were *2 vs 3 analysts* and *15 vs 16 minute escalation timer*, and the triage time was recorded manually from memory at shift end. What is the MOST likely explanation?",options:["Levels that were too close together and a noisy measurement system made real effects undetectable","The factors truly have no effect on triage time","The experiment had too many replicates","The design was not orthogonal"],answer:0,hint:"Signal (level spread) vs noise (process + measurement error) decides detectability.",steps:[{title:"Key idea",body:"A one-minute change in the timer is a tiny signal, and recall-based recording adds large measurement error."},{title:"Fix",body:"Use bolder levels (e.g. 10 vs 20 minutes) and a system timestamp for the response."}],final:"Weak signal + noisy measurement → answer **A**",whyWrong:["","Possible, but the narrow levels and poor measurement mean the experiment had little chance of detecting effects.","More replicates make detection easier, not harder.","Two-level factorials are orthogonal; the problem is the signal-to-noise ratio."],trap:"“No significant effect” is not proof that there is no effect.",bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb099",phase:4,topic:"4.3.3",qtype:"concept",difficulty:2,stem:"A team must choose between **more factors** and **more replicates** for a fixed budget of 32 runs. Which consideration matters MOST?",options:["Whether the main risk is missing an important X (favour more factors in a fraction) or estimating effects precisely (favour replicates)","More factors are always better because replication adds no information","More replicates are always better because fractional designs are invalid","The choice does not matter because the total runs are the same"],answer:0,hint:"Budget trade-off: breadth (screening more X’s) vs depth (precision, interactions).",steps:[{title:"Key idea",body:"Early on, missing a vital X is the bigger risk, so screening more factors with a fraction is sensible. Later, precision and interactions matter more, so replicate or use a full factorial."},{title:"Apply",body:"Match the design to the experimental objective."}],final:"Match the trade-off to the objective → answer **A**",whyWrong:["","Replication gives the pure error estimate and better precision.","Fractional designs are valid; they trade aliasing for runs.","The same runs can give very different information depending on the design."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb100",phase:4,topic:"4.3.3",qtype:"concept",difficulty:1,stem:"Who should normally be involved in planning a DOE on a live service process?",options:["Only the Black Belt, to keep the design statistically pure","Only senior management, because they approve the budget","The process owner, people who run the process and subject-matter experts, as well as the Black Belt","Only the vendor, because they know the system best"],answer:2,hint:"DOE planning is a team activity: statistics + process knowledge + ownership.",steps:[{title:"Key idea",body:"Process experts suggest factors and realistic levels, spot practical risks and help run the experiment correctly."},{title:"Benefit",body:"Ownership also helps the results get implemented."}],final:"Involve owner, operators and SMEs → answer **C**",whyWrong:["Without process knowledge, factors and levels may be unrealistic or unsafe.","Approval matters, but the people who run the process know what is feasible.","","Vendor input can help, but the operator owns the process and the risk."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb101",phase:4,topic:"4.3.3",qtype:"concept",difficulty:2,stem:"Why is it risky to run every run of an experiment on the same **single** server, if the results will be used for the whole server farm?",options:["A single server cannot produce a valid ANOVA","Using one server always creates aliasing","It makes randomization impossible","The conclusions may not apply to other servers (narrow inference space)"],answer:3,hint:"Inference space: results apply to the conditions that were sampled.",steps:[{title:"Key idea",body:"Holding a nuisance factor constant reduces noise but narrows where the conclusions apply."},{title:"Balance",body:"Including several servers as blocks broadens the inference while keeping noise under control."}],final:"Narrow inference space → answer **D**",whyWrong:["The ANOVA is valid, but the results describe that server only.","Aliasing comes from the design structure, not from the number of servers.","Runs can still be randomized on one server.",""],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb102",phase:4,topic:"4.3.3",qtype:"concept",difficulty:2,stem:"What is the main danger of a factor level combination in the design that is **impossible to run** (e.g. a “high” bandwidth that the old modem cannot support)?",options:["It only reduces the error degrees of freedom slightly","Runs will be missing or substituted, which breaks balance and orthogonality and can bias effects","It has no effect if the run is simply skipped","It automatically increases the resolution"],answer:1,hint:"Check feasibility of every combination before running (pilot / constraints).",steps:[{title:"Key idea",body:"A factorial relies on every combination being run. If one cannot be run, the effects are no longer estimated independently."},{title:"Fix",body:"Adjust levels, or use a constrained (e.g. optimal) design."}],final:"Breaks balance and orthogonality → answer **B**",whyWrong:["A missing corner can do far more than that: it unbalances the design and correlates the estimates.","","Skipping a run makes the design unbalanced and non-orthogonal.","Missing runs never improve resolution."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb103",phase:4,topic:"4.3.3",qtype:"scenario",difficulty:2,stem:"A team plans its DOE on **5G handover success** to run in standard order because “it is easier for the engineers.” Weekend traffic is much lighter than weekday traffic and the experiment spans a week. What is the main design concern?",options:["Standard order will reduce the number of effects that can be estimated","Factors that change slowly in standard order will be confounded with the weekday/weekend traffic pattern","There is no concern because traffic is a noise factor","The design will lose its balance"],answer:1,hint:"Systematic order + time-related nuisance = confounding. Randomize and/or block by day type.",steps:[{title:"Key idea",body:"In standard order the last factor changes only once, so it lines up with any trend over the week."},{title:"Fix",body:"Randomize, and block by weekday vs weekend if the difference is large."}],final:"Confounding with time → answer **B**",whyWrong:["The number of estimable effects is the same; the problem is bias.","","Traffic is a nuisance that changes systematically with time, so it can bias effects that also change with time.","The design stays balanced; it becomes confounded with time."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb104",phase:4,topic:"4.3.3",qtype:"concept",difficulty:2,stem:"During screening-experiment planning, the team is unsure whether **DNS cache TTL** affects web-page load time. What is the generally recommended approach?",options:["Leave it out: every extra factor doubles the runs in a fractional design","Leave it out and assume its effect will show up in the residuals","Include it: leaving out a vital X cannot be fixed later, while an extra column in a fractional design costs little","Include it only if the budget allows a full factorial"],answer:2,hint:"Screening: when in doubt, include the factor (cheap); omission is the costly error.",steps:[{title:"Key idea",body:"The purpose of screening is to avoid missing a vital X. A $2^{k-p}$ or Plackett–Burman design can absorb an extra factor with few or no extra runs."},{title:"Risk balance",body:"A trivial factor wastes one column; a missing vital factor wastes the whole project."}],final:"Include doubtful factors when screening → answer **C**",whyWrong:["In a fractional design an extra factor can often be added to an existing column without adding runs.","An omitted factor that varies adds noise or bias; its effect cannot be estimated from residuals.","","Screening designs exist precisely so that doubtful factors can be included cheaply."],bookRef:"Syllabus 4.3.3"},{id:"sv-4-bb105",phase:4,topic:"4.3.3",qtype:"missing-word",difficulty:1,stem:"Complete the sentence: “Holding a nuisance variable at one fixed value reduces experimental noise, but it also narrows the [?] — the range of conditions to which the conclusions apply.”",options:["inference space","resolution","error degrees of freedom","design generator"],answer:0,hint:"Fixing nuisance variables: less noise, narrower inference space.",steps:[{title:"Key idea",body:"Results from one site, one shift or one server type apply with confidence only to that condition."},{title:"Trade-off",body:"Blocking over several conditions widens the inference space while still removing the nuisance from the error."}],final:"Inference space → answer **A**",whyWrong:["","Resolution describes aliasing in fractional designs, not where results apply.","Holding a variable constant does not change the error df.","A generator defines how a fractional design is built."],bookRef:"Syllabus 4.3.3"}];export{e as items};
